INSERT INTO public.pokemons (id, name, shiny, image, description_pt) VALUES
(1, 'Bulbasaur', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1.png', 'Uma estranha semente foi plantada nas suas costas ao nascer. A planta brota e cresce com este POKéMON.'),
(2, 'Ivysaur', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/2.png', 'Quando o bulbo em suas costas cresce, ele parece perder a capacidade de ficar em pé sobre as patas traseiras.'),
(3, 'Venusaur', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/3.png', 'A planta floresce quando absorve energia solar. Ele permanece em movimento em busca da luz solar.'),
(4, 'Charmander', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/4.png', 'Obviamente prefere lugares quentes. Quando chove, diz-se que o vapor sai da ponta da cauda.'),
(5, 'Charmeleon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/5.png', 'Quando balança a cauda em chamas, eleva a temperatura a níveis insuportavelmente altos.'),
(6, 'Charizard', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/6.png', 'Cospe fogo quente o suficiente para derreter pedras. Conhecido por causar incêndios florestais involuntariamente.'),
(7, 'Squirtle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/7.png', 'Após o nascimento, suas costas incha e endurece formando uma concha. Pulveriza espuma poderosamente pela boca.'),
(8, 'Wartortle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/8.png', 'Freqüentemente se esconde na água para perseguir presas incautas. Para nadar rápido, ele move as orelhas para manter o equilíbrio.'),
(9, 'Blastoise', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/9.png', 'Um POKéMON brutal com jatos de água pressurizada em sua concha. Eles são usados ​​para tackles de alta velocidade.'),
(10, 'Caterpie', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/10.png', 'Seus pés curtos possuem ventosas nas pontas que lhe permitem escalar encostas e paredes incansavelmente.'),
(11, 'Metapod', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/11.png', 'Este POKéMON é vulnerável a ataques enquanto sua carapaça é macia, expondo seu corpo fraco e sensível.'),
(12, 'Butterfree', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/12.png', 'Na batalha, ele bate as asas em alta velocidade para liberar poeira altamente tóxica no ar.'),
(13, 'Weedle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/13.png', 'Frequentemente encontrado em florestas, comendo folhas. Possui um ferrão venenoso afiado na cabeça.'),
(14, 'Kakuna', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/14.png', 'Quase incapaz de se mover, este POKéMON só consegue endurecer a sua carapaça para se proteger dos predadores.'),
(15, 'Beedrill', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/15.png', 'Voa em alta velocidade e ataca usando seus grandes ferrões venenosos nas patas dianteiras e na cauda.'),
(16, 'Pidgey', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/16.png', 'Uma visão comum em florestas e bosques. Ele bate as asas ao nível do solo para levantar areia ofuscante.'),
(17, 'Pidgeotto', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/17.png', 'Muito protetor da sua extensa área territorial, este POKéMON bicará ferozmente qualquer intruso.'),
(18, 'Pidgeot', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/18.png', 'Ao caçar, ele desliza pela superfície da água em alta velocidade para capturar presas incautas, como MAGIKARP.'),
(19, 'Rattata', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/19.png', 'Morde qualquer coisa quando ataca. Pequeno e muito rápido, é comum em muitos lugares.'),
(20, 'Raticate', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/20.png', 'Ele usa seus bigodes para manter o equilíbrio. Aparentemente, fica mais lento se eles forem cortados.'),
(21, 'Spearow', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/21.png', 'Come insetos em áreas gramadas. Ele precisa bater suas asas curtas em alta velocidade para permanecer no ar.'),
(22, 'Fearow', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/22.png', 'Com as suas enormes e magníficas asas, consegue manter-se no ar sem ter de aterrar para descansar.'),
(23, 'Ekans', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/23.png', 'Move-se silenciosa e furtivamente. Come ovos inteiros de pássaros, como PIDGEY e SPEAROW.'),
(24, 'Arbok', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/24.png', 'Há rumores de que as ferozes marcas de alerta em sua barriga diferem de área para área.'),
(25, 'Pikachu', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/25.png', 'Quando vários desses POKéMON se reúnem, sua eletricidade pode aumentar e causar tempestades com raios.'),
(26, 'Raichu', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/26.png', 'Sua longa cauda serve como aterramento para se proteger de sua própria energia de alta tensão.'),
(27, 'Sandshrew', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/27.png', 'Enterra-se no subsolo em locais áridos, longe da água. Ele só surge para caçar comida.'),
(28, 'Sandslash', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/28.png', 'Enrola-se em uma bola espinhosa quando ameaçado. Ele pode rolar enquanto está enrolado para atacar ou escapar.'),
(29, 'Nidoran-f', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/29.png', 'Embora pequeno, suas farpas venenosas tornam este POKéMON perigoso. A fêmea tem chifres menores.'),
(30, 'Nidorina', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/30.png', 'O chifre da fêmea se desenvolve lentamente. Prefere ataques físicos, como arranhar e morder.'),
(31, 'Nidoqueen', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/31.png', 'Suas escamas duras proporcionam forte proteção. Ele usa seu corpo robusto para executar movimentos poderosos.'),
(32, 'Nidoran-m', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/32.png', 'Endurece seus ouvidos para sentir o perigo. Quanto maiores forem seus chifres, mais poderoso será o veneno secretado.'),
(33, 'Nidorino', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/33.png', 'Um POKéMON agressivo que ataca rapidamente. O chifre em sua cabeça secreta um veneno poderoso.'),
(34, 'Nidoking', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/34.png', 'Ele usa sua poderosa cauda em batalha para esmagar, contrair e depois quebrar os ossos da presa.'),
(35, 'Clefairy', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/35.png', 'Seu apelo mágico e fofo tem muitos admiradores. É raro e encontrado apenas em certas áreas.'),
(36, 'Clefable', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/36.png', 'Uma fada POKéMON tímida que raramente é vista. Ele correrá e se esconderá no momento em que sentir as pessoas.'),
(37, 'Vulpix', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/37.png', 'No momento do nascimento, possui apenas uma cauda. A cauda se divide na ponta à medida que envelhece.'),
(38, 'Ninetales', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/38.png', 'Muito inteligente e muito vingativo. Agarrar uma de suas muitas caudas poderia resultar em uma maldição de 1000 anos.'),
(39, 'Jigglypuff', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/39.png', 'Quando seus enormes olhos se iluminam, ele canta uma melodia misteriosamente calmante que faz seus inimigos dormirem.'),
(40, 'Wigglytuff', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/40.png', 'O corpo é macio e emborrachado. Quando irritado, ele irá sugar o ar e inflar até atingir um tamanho enorme.'),
(41, 'Zubat', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/41.png', 'Forma colônias em locais perpetuamente escuros. Usa ondas ultrassônicas para identificar e aproximar alvos.'),
(42, 'Golbat', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/42.png', 'Uma vez atingido, não parará de drenar energia da vítima, mesmo que fique pesado demais para voar.'),
(43, 'Oddish', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/43.png', 'Durante o dia, mantém o rosto enterrado no chão. À noite, ele vagueia semeando suas sementes.'),
(44, 'Gloom', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/44.png', 'O fluido que escorre da boca não é baba. É um néctar usado para atrair presas.'),
(45, 'Vileplume', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/45.png', 'Quanto maiores forem suas pétalas, mais pólen tóxico ela contém. Sua cabeça grande é pesada e difícil de segurar.'),
(46, 'Paras', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/46.png', 'Tocas para sugar raízes de árvores. Os cogumelos em suas costas crescem extraindo nutrientes do inseto hospedeiro.'),
(47, 'Parasect', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/47.png', 'Um par hospedeiro-parasita no qual o cogumelo parasita assumiu o controle do inseto hospedeiro. Prefere locais úmidos.'),
(48, 'Venonat', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/48.png', 'Vive à sombra de árvores altas onde se alimenta de insetos. É atraído pela luz à noite.'),
(49, 'Venomoth', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/49.png', 'As escamas semelhantes a poeira que cobrem suas asas são codificadas por cores para indicar os tipos de veneno que possui.'),
(50, 'Diglett', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/50.png', 'Vive cerca de um metro abaixo do solo, onde se alimenta de raízes de plantas. Às vezes aparece acima do solo.'),
(51, 'Dugtrio', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/51.png', 'Uma equipe de trigêmeos DIGLETT. Ele desencadeia enormes terremotos ao cavar 60 milhas no subsolo.'),
(52, 'Meowth', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/52.png', 'Adora objetos circulares. Vagueia pelas ruas todas as noites em busca de trocos perdidos.'),
(53, 'Persian', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/53.png', 'Embora seu pelo tenha muitos admiradores, é difícil criá-lo como animal de estimação por causa de sua maldade inconstante.'),
(54, 'Psyduck', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/54.png', 'Enquanto acalma seus inimigos com seu olhar vazio, este astuto POKéMON usará poderes psicocinéticos.'),
(55, 'Golduck', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/55.png', 'Frequentemente visto nadando elegantemente nas margens do lago. Muitas vezes é confundido com o monstro japonês Kappa.'),
(56, 'Mankey', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/56.png', 'Extremamente rápido em ficar com raiva. Poderia ser dócil em um momento e depois se debater no instante seguinte.'),
(57, 'Primeape', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/57.png', 'Sempre furioso e tenaz para arrancar. Não abandonará a perseguição à sua presa até ser capturada.'),
(58, 'Growlithe', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/58.png', 'Muito protetor de seu território. Ele latirá e morderá para repelir intrusos de seu espaço.'),
(59, 'Arcanine', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/59.png', 'Um POKéMON que é admirado desde o passado por sua beleza. Ele corre agilmente como se tivesse asas.'),
(60, 'Poliwag', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/60.png', 'Suas pernas recém-crescidas o impedem de correr. Parece preferir nadar a tentar ficar de pé.'),
(61, 'Poliwhirl', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/61.png', 'Capaz de viver dentro ou fora da água. Quando está fora d''água, ele transpira para manter o corpo viscoso.'),
(62, 'Poliwrath', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/62.png', 'Um nadador experiente tanto no nado crawl quanto no nado peito. Ultrapassa facilmente os melhores nadadores humanos.'),
(63, 'Abra', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/63.png', 'Usando sua capacidade de ler mentes, ele identificará perigos iminentes e se teletransportará para um local seguro.'),
(64, 'Kadabra', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/64.png', 'Ele emite ondas alfa especiais de seu corpo que provocam dores de cabeça apenas por estar por perto.'),
(65, 'Alakazam', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/65.png', 'Seu cérebro pode superar um supercomputador. Diz-se que seu quociente de inteligência é de 5.000.'),
(66, 'Machop', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/66.png', 'Adora construir seus músculos. Ele treina todos os estilos de artes marciais para se tornar ainda mais forte.'),
(67, 'Machoke', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/67.png', 'Seu corpo musculoso é tão poderoso que ele deve usar um cinto economizador de energia para poder regular seus movimentos.'),
(68, 'Machamp', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/68.png', 'Usando seus músculos pesados, ele desfere socos poderosos que podem lançar a vítima para longe do horizonte.'),
(69, 'Bellsprout', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/69.png', 'Um POKéMON carnívoro que captura e come insetos. Ele usa seus pés de raiz para absorver a umidade necessária.'),
(70, 'Weepinbell', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/70.png', 'Ele cospe POISONPOWDER para imobilizar o inimigo e depois finaliza com um spray de ÁCIDO.'),
(71, 'Victreebel', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/71.png', 'Diz-se que vivem em enormes colônias nas profundezas da selva, embora ninguém tenha retornado de lá.'),
(72, 'Tentacool', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/72.png', 'Deriva em mares rasos. Os pescadores que os fisgam acidentalmente são frequentemente punidos pelo seu ácido pungente.'),
(73, 'Tentacruel', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/73.png', 'Os tentáculos normalmente são curtos. Nas caçadas, eles são estendidos para capturar e imobilizar as presas.'),
(74, 'Geodude', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/74.png', 'Encontrado em campos e montanhas. Confundindo-os com pedras, as pessoas muitas vezes pisam ou tropeçam neles.'),
(75, 'Graveler', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/75.png', 'Desce encostas para se mover. Ele rola sobre qualquer obstáculo sem diminuir a velocidade ou mudar de direção.'),
(76, 'Golem', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/76.png', 'Seu corpo parecido com uma pedra é extremamente duro. Ele pode suportar facilmente explosões de dinamite sem danos.'),
(77, 'Ponyta', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/77.png', 'Seus cascos são 10 vezes mais duros que os diamantes. Ele pode pisotear qualquer coisa completamente plana em pouco tempo.'),
(78, 'Rapidash', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/78.png', 'Muito competitivo, este POKéMON irá perseguir qualquer coisa que se mova rapidamente na esperança de competir com ele.'),
(79, 'Slowpoke', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/79.png', 'Incrivelmente lento e estúpido. Demora 5 segundos para sentir dor quando está sob ataque.'),
(80, 'Slowbro', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/80.png', 'Diz-se que o SHELLDER que está preso na cauda do SLOWPOKE se alimenta das sobras do hospedeiro.'),
(81, 'Magnemite', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/81.png', 'Usa antigravidade para permanecer suspenso. Aparece sem aviso e usa THUNDER WAVE e movimentos semelhantes.'),
(82, 'Magneton', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/82.png', 'Formado por vários MAGNEMITEs interligados. Eles freqüentemente aparecem quando as manchas solares aumentam.'),
(83, 'Farfetchd', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/83.png', 'O raminho de cebolinha que ele segura é sua arma. É usado como uma espada de metal.'),
(84, 'Doduo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/84.png', 'Um pássaro que compensa seu péssimo vôo com sua rápida velocidade. Deixa pegadas gigantes.'),
(85, 'Dodrio', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/85.png', 'Usa seus três cérebros para executar planos complexos. Enquanto duas cabeças dormem, uma cabeça permanece acordada.'),
(86, 'Seel', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/86.png', 'O chifre saliente em sua cabeça é muito duro. É usado para quebrar gelo espesso.'),
(87, 'Dewgong', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/87.png', 'Armazena energia térmica em seu corpo. Nada a 8 nós constantes, mesmo em águas intensamente frias.'),
(88, 'Grimer', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/88.png', 'Aparece em áreas sujas. Prospera sugando o lodo poluído que é bombeado para fora das fábricas.'),
(89, 'Muk', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/89.png', 'Espessamente coberto com um lodo imundo e vil. É tão tóxico que até suas pegadas contêm veneno.'),
(90, 'Shellder', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/90.png', 'Sua casca dura repele qualquer tipo de ataque. É vulnerável apenas quando seu shell está aberto.'),
(91, 'Cloyster', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/91.png', 'Quando atacado, lança seus chifres em rajadas rápidas. Suas entranhas nunca foram vistas.'),
(92, 'Gastly', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/92.png', 'Quase invisível, este POKéMON gasoso encobre o alvo e o coloca para dormir sem aviso prévio.'),
(93, 'Haunter', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/93.png', 'Devido à sua capacidade de deslizar através de paredes de blocos, diz-se que é de outra dimensão.'),
(94, 'Gengar', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/94.png', 'Sob a lua cheia, este POKéMON gosta de imitar as sombras das pessoas e rir do seu susto.'),
(95, 'Onix', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/95.png', 'À medida que cresce, as partes de pedra do seu corpo endurecem e se tornam semelhantes a um diamante, mas de cor preta.'),
(96, 'Drowzee', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/96.png', 'Coloca os inimigos para dormir e depois come seus sonhos. Ocasionalmente fica doente por comer pesadelos.'),
(97, 'Hypno', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/97.png', 'Ao encarar um inimigo, ele usará uma mistura de movimentos PSI, como HYPNOSIS e CONFUSION.'),
(98, 'Krabby', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/98.png', 'Suas pinças não são apenas armas poderosas, elas são usadas para manter o equilíbrio ao caminhar de lado.'),
(99, 'Kingler', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/99.png', 'A grande pinça tem 10.000 HP de poder de esmagamento. No entanto, seu enorme tamanho torna seu uso difícil.'),
(100, 'Voltorb', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/100.png', 'Geralmente encontrado em usinas de energia. Facilmente confundidos com uma POKé BALL, eles eletrocutaram muitas pessoas.'),
(101, 'Electrode', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/101.png', 'Armazena energia elétrica sob pressão muito alta. Muitas vezes explode com pouca ou nenhuma provocação.'),
(102, 'Exeggcute', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/102.png', 'Muitas vezes confundido com ovos. Quando perturbados, eles rapidamente se reúnem e atacam em enxames.'),
(103, 'Exeggutor', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/103.png', 'Diz a lenda que, em raras ocasiões, uma de suas cabeças cairá e continuará como EXEGGCUTE.'),
(104, 'Cubone', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/104.png', 'Como ele nunca remove seu capacete de caveira, ninguém jamais viu o verdadeiro rosto deste POKéMON.'),
(105, 'Marowak', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/105.png', 'O osso que ele segura é sua arma principal. Ele joga o osso habilmente como um bumerangue para nocautear alvos.'),
(106, 'Hitmonlee', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/106.png', 'Quando está com pressa, suas pernas alongam-se progressivamente. Ele corre suavemente com passadas extra longas e galopantes.'),
(107, 'Hitmonchan', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/107.png', 'Embora aparentemente não faça nada, ele dispara socos em rajadas extremamente rápidas que são impossíveis de ver.'),
(108, 'Lickitung', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/108.png', 'Sua língua pode ser estendida como a de um camaleão. Deixa uma sensação de formigamento ao lamber os inimigos.'),
(109, 'Koffing', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/109.png', 'Por armazenar vários tipos de gases tóxicos em seu corpo, é propenso a explodir sem aviso prévio.'),
(110, 'Weezing', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/110.png', 'Onde dois tipos de gases venenosos se encontram, 2 KOFFINGs podem se fundir em um WEEZING ao longo de muitos anos.'),
(111, 'Rhyhorn', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/111.png', 'Seus ossos enormes são 1000 vezes mais duros que os ossos humanos. Ele pode facilmente derrubar um trailer.'),
(112, 'Rhydon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/112.png', 'Protegido por uma pele semelhante a uma armadura, é capaz de viver em lava derretida a 3.600 graus.'),
(113, 'Chansey', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/113.png', 'Um POKéMON raro e evasivo que dizem trazer felicidade para aqueles que conseguem obtê-la.'),
(114, 'Tangela', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/114.png', 'Todo o corpo é coberto por largas trepadeiras semelhantes a algas marinhas. Suas vinhas tremem enquanto caminha.'),
(115, 'Kangaskhan', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/115.png', 'O bebê raramente sai da bolsa protetora da mãe até os 3 anos de idade.'),
(116, 'Horsea', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/116.png', 'Conhecido por abater insetos voadores com jatos precisos de tinta da superfície da água.'),
(117, 'Seadra', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/117.png', 'Capaz de nadar para trás batendo rapidamente suas nadadeiras peitorais em forma de asa e sua cauda robusta.'),
(118, 'Goldeen', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/118.png', 'Sua barbatana caudal ondula como um elegante vestido de baile, dando-lhe o apelido de Rainha da Água.'),
(119, 'Seaking', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/119.png', 'Na época de desova do outono, eles podem ser vistos nadando com força em rios e riachos.'),
(120, 'Staryu', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/120.png', 'Um POKéMON enigmático que pode regenerar facilmente qualquer apêndice que perder em batalha.'),
(121, 'Starmie', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/121.png', 'Seu núcleo central brilha com as sete cores do arco-íris. Algumas pessoas valorizam o núcleo como uma joia.'),
(122, 'Mr-mime', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/122.png', 'Se for interrompido durante a mímica, ele dará tapas no agressor com suas mãos largas.'),
(123, 'Scyther', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/123.png', 'Com agilidade e velocidade ninja, pode criar a ilusão de que existe mais de um.'),
(124, 'Jynx', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/124.png', 'Ele balança sedutoramente os quadris enquanto caminha. Pode fazer com que as pessoas dancem em uníssono com ele.'),
(125, 'Electabuzz', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/125.png', 'Normalmente encontrados perto de usinas de energia, eles podem se afastar e causar grandes apagões nas cidades.'),
(126, 'Magmar', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/126.png', 'Seu corpo sempre queima com um brilho laranja que lhe permite se esconder perfeitamente entre as chamas.'),
(127, 'Pinsir', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/127.png', 'Se não conseguir esmagar a vítima com suas pinças, ele a balançará e a lançará com força.'),
(128, 'Tauros', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/128.png', 'Quando atinge um inimigo, ele ataca furiosamente enquanto chicoteia seu corpo com suas longas caudas.'),
(129, 'Magikarp', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/129.png', 'No passado distante, era um pouco mais forte do que os descendentes terrivelmente fracos que existem hoje.'),
(130, 'Gyarados', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/130.png', 'Raramente visto na natureza. Enorme e cruel, é capaz de destruir cidades inteiras num acesso de fúria.'),
(131, 'Lapras', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/131.png', 'Um POKéMON que foi caçado quase até a extinção. Ele pode transportar pessoas através da água.'),
(132, 'Ditto', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/132.png', 'Capaz de copiar o código genético de um inimigo para se transformar instantaneamente em uma duplicata do inimigo.'),
(133, 'Eevee', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/133.png', 'Seu código genético é irregular. Ele pode sofrer mutação se for exposto à radiação dos elementos STONEs.'),
(134, 'Vaporeon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/134.png', 'Vive perto da água. Sua longa cauda é estriada por uma barbatana que muitas vezes é confundida com a de uma sereia.'),
(135, 'Jolteon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/135.png', 'Ele acumula íons negativos na atmosfera para lançar raios de 10.000 volts.'),
(136, 'Flareon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/136.png', 'Ao armazenar energia térmica em seu corpo, sua temperatura poderia subir para mais de 1.600 graus.'),
(137, 'Porygon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/137.png', 'Um POKéMON que consiste inteiramente em código de programação. Capaz de circular livremente no ciberespaço.'),
(138, 'Omanyte', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/138.png', 'Embora extinto há muito tempo, em casos raros, pode ser ressuscitado geneticamente a partir de fósseis.'),
(139, 'Omastar', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/139.png', 'Um POKéMON pré-histórico que morreu quando sua carapaça pesada impossibilitou a captura de uma presa.'),
(140, 'Kabuto', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/140.png', 'Um POKéMON que foi ressuscitado de um fóssil encontrado no que já foi o fundo do oceano há muito tempo.'),
(141, 'Kabutops', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/141.png', 'Seu formato elegante é perfeito para nadar. Ele corta a presa com suas garras e drena os fluidos corporais.'),
(142, 'Aerodactyl', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/142.png', 'Um POKéMON feroz e pré-histórico que atinge a garganta do inimigo com suas presas serrilhadas em forma de serra.'),
(143, 'Snorlax', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/143.png', 'Muito preguiçoso. Apenas come e dorme. À medida que seu volume rotundo aumenta, ele se torna cada vez mais preguiçoso.'),
(144, 'Articuno', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/144.png', 'Um lendário pássaro POKéMON que supostamente aparece para pessoas condenadas que estão perdidas em montanhas geladas.'),
(145, 'Zapdos', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/145.png', 'Um pássaro lendário POKéMON que supostamente aparece das nuvens enquanto lança enormes raios.'),
(146, 'Moltres', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/146.png', 'Conhecido como o lendário pássaro de fogo. Cada batida de suas asas cria um brilho deslumbrante de chamas.'),
(147, 'Dratini', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/147.png', 'Há muito considerado um POKéMON mítico até recentemente, quando uma pequena colônia foi encontrada vivendo debaixo d’água.'),
(148, 'Dragonair', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/148.png', 'Um POKéMON místico que exala uma aura gentil. Tem a capacidade de alterar as condições climáticas.'),
(149, 'Dragonite', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/149.png', 'Um POKéMON marinho extremamente raramente visto. Diz-se que sua inteligência corresponde à dos humanos.'),
(150, 'Mewtwo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/150.png', 'Foi criado por um cientista após anos de horríveis experimentos de emenda de genes e engenharia de DNA.'),
(151, 'Mew', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/151.png', 'Tão raro que ainda é considerado uma miragem por muitos especialistas. Apenas algumas pessoas viram isso em todo o mundo.'),
(152, 'Chikorita', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/152.png', 'Um aroma doce emana suavemente da folha em sua cabeça. É dócil e adora absorver os raios solares.'),
(153, 'Bayleef', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/153.png', 'O cheiro de especiarias vem do pescoço. De alguma forma, cheirá-lo dá vontade de lutar.'),
(154, 'Meganium', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/154.png', 'O aroma que sai de suas pétalas contém uma substância que acalma sentimentos agressivos.'),
(155, 'Cyndaquil', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/155.png', 'É tímido e sempre se enrola como uma bola. Se atacado, ele ergue as costas para proteção.'),
(156, 'Quilava', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/156.png', 'Tenha cuidado se ele virar as costas durante a batalha. Isso significa que ele atacará com o fogo nas costas.'),
(157, 'Typhlosion', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/157.png', 'Se sua raiva atingir o pico, ele ficará tão quente que qualquer coisa que o toque irá instantaneamente pegar fogo.'),
(158, 'Totodile', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/158.png', 'Suas mandíbulas bem desenvolvidas são poderosas e capazes de esmagar qualquer coisa. Até o seu treinador deve ter cuidado.'),
(159, 'Croconaw', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/159.png', 'Se perder uma presa, uma nova crescerá em seu lugar. Sempre há 48 presas em sua boca.'),
(160, 'Feraligatr', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/160.png', 'Quando morde com suas mandíbulas enormes e poderosas, ele balança a cabeça e rasga selvagemente sua vítima.'),
(161, 'Sentret', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/161.png', 'Um POKéMON muito cauteloso, ele se levanta usando a cauda para ter uma visão melhor do que está ao seu redor.'),
(162, 'Furret', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/162.png', 'Faz um ninho adequado ao seu corpo longo e magro. O ninho é impossível para outros POKéMON entrarem.'),
(163, 'Hoothoot', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/163.png', 'Ele sempre fica em um pé só. Ele muda de pé tão rápido que o movimento raramente pode ser visto.'),
(164, 'Noctowl', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/164.png', 'Seus olhos são especialmente adaptados. Eles concentram até mesmo a luz fraca e permitem ver no escuro.'),
(165, 'Ledyba', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/165.png', 'É muito tímido. Terá medo de se mover se estiver sozinho. Mas estará ativo se estiver em grupo.'),
(166, 'Ledian', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/166.png', 'Quando as estrelas piscam no céu noturno, elas flutuam, espalhando um pó brilhante.'),
(167, 'Spinarak', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/167.png', 'Ele permanece na mesma posição durante dias em sua teia, esperando que sua presa desavisada se aproxime.'),
(168, 'Ariados', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/168.png', 'Ele gira a corda não apenas pela parte traseira, mas também pela boca. É difícil dizer qual fim é qual.'),
(169, 'Crobat', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/169.png', 'Ele voa tão silenciosamente através da escuridão com suas quatro asas que pode não ser notado mesmo quando está por perto.'),
(170, 'Chinchou', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/170.png', 'Ele dispara eletricidade positiva e negativa entre as pontas de suas duas antenas e atinge seus inimigos.'),
(171, 'Lanturn', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/171.png', 'A luz que emite é tão brilhante que pode iluminar a superfície do mar a uma profundidade de mais de cinco quilómetros.'),
(172, 'Pichu', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/172.png', 'Ainda não tem habilidade para armazenar eletricidade. Pode causar um choque se estiver divertido ou assustado.'),
(173, 'Cleffa', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/173.png', 'Por causa de sua silhueta incomum, parecida com uma estrela, as pessoas acreditam que ele veio aqui em um meteoro.'),
(174, 'Igglybuff', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/174.png', 'Tem um corpo muito macio. Se começar a rolar, saltará e será impossível pará-lo.'),
(175, 'Togepi', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/175.png', 'A concha parece estar cheia de alegria. Diz-se que ele compartilhará boa sorte quando tratado com gentileza.'),
(176, 'Togetic', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/176.png', 'Dizem que ele aparecerá diante de pessoas bondosas e atenciosas e as encherá de felicidade.'),
(177, 'Natu', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/177.png', 'Como suas asas ainda não estão totalmente crescidas, ele precisa pular para se locomover. Está sempre olhando para alguma coisa.'),
(178, 'Xatu', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/178.png', 'Dizem que ele fica quieto e quieto porque vê o passado e o futuro ao mesmo tempo.'),
(179, 'Mareep', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/179.png', 'Se a eletricidade estática se acumular em seu corpo, seu velo dobra de volume. Tocá-lo irá chocá-lo.'),
(180, 'Flaaffy', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/180.png', 'Como resultado do armazenamento excessivo de eletricidade, desenvolveu áreas onde nem mesmo a lã felpuda cresce.'),
(181, 'Ampharos', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/181.png', 'A ponta da cauda brilha intensamente e pode ser vista de longe. Ele atua como um farol para pessoas perdidas.'),
(182, 'Bellossom', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/182.png', 'BELLOSSOM às vezes se reúne e parece dançar. Dizem que a dança é um ritual para invocar o sol.'),
(183, 'Marill', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/183.png', 'A ponta da cauda, ​​que contém um óleo mais leve que a água, permite-lhe nadar sem se afogar.'),
(184, 'Azumarill', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/184.png', 'Mantendo-se quieto e ouvindo atentamente, ele pode dizer o que está acontecendo até mesmo em rios selvagens e de movimento rápido.'),
(185, 'Sudowoodo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/185.png', 'Embora sempre finja ser uma árvore, sua composição parece mais próxima de uma rocha do que de uma planta.'),
(186, 'Politoed', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/186.png', 'Se POLIWAG e POLIWHIRL ouvirem seu grito ecoante, eles responderão reunindo-se de longe.'),
(187, 'Hoppip', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/187.png', 'Para não serem levados pelo vento, eles se reúnem em grupos. Eles gostam de brisas suaves, no entanto.'),
(188, 'Skiploom', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/188.png', 'A flor no topo de sua cabeça abre e fecha conforme a temperatura oscila para cima e para baixo.'),
(189, 'Jumpluff', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/189.png', 'Assim que pega o vento, ele habilmente controla seus esporos de algodão para flutuarem, até mesmo em todo o mundo.'),
(190, 'Aipom', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/190.png', 'Sua cauda é tão poderosa que ele pode usá-la para agarrar um galho de árvore e se manter no ar.'),
(191, 'Sunkern', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/191.png', 'Pode cair do céu de repente. Se for atacado por uma LANÇA, ela sacudirá violentamente suas folhas.'),
(192, 'Sunflora', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/192.png', 'Ele converte a luz solar em energia. Na escuridão após o pôr do sol, ele fecha as pétalas e fica imóvel.'),
(193, 'Yanma', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/193.png', 'Se bater as asas muito rápido, poderá gerar ondas de choque que quebrarão janelas na área.'),
(194, 'Wooper', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/194.png', 'Este POKéMON vive em água fria. Ele sairá da água em busca de comida quando esfriar lá fora.'),
(195, 'Quagsire', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/195.png', 'Este POKéMON despreocupado tem uma natureza descontraída. Ao nadar, sempre esbarra nos cascos dos barcos.'),
(196, 'Espeon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/196.png', 'Ele usa os pelos finos que cobrem seu corpo para sentir as correntes de ar e prever as ações de seus inimigos.'),
(197, 'Umbreon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/197.png', 'Quando agitado, este POKéMON se protege espirrando suor venenoso pelos poros.'),
(198, 'Murkrow', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/198.png', 'Temido e odiado por muitos, acredita-se que traz infortúnio a todos aqueles que o veem à noite.'),
(199, 'Slowking', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/199.png', 'Tem um intelecto incrível e uma mensalidade. Seja qual for a situação, ele permanece calmo e controlado.'),
(200, 'Misdreavus', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/200.png', 'Gosta de pregar peças maliciosas, como gritar e chorar, para assustar as pessoas à noite.'),
(201, 'Unown', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/201.png', 'Suas formas parecem hieróglifos em tablaturas antigas. Diz-se que os dois estão de alguma forma relacionados.'),
(202, 'Wobbuffet', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/202.png', 'Ele odeia luz e choque. Se for atacado, ele infla seu corpo para aumentar seu contra-ataque.'),
(203, 'Girafarig', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/203.png', 'Sua cauda possui um pequeno cérebro próprio. Cuidado! Se você chegar perto, ele pode reagir ao seu cheiro e morder.'),
(204, 'Pineco', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/204.png', 'Gosta de engrossar a casca adicionando camadas de casca de árvore. O peso adicional não incomoda.'),
(205, 'Forretress', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/205.png', 'Todo o seu corpo é protegido por uma casca dura de aço. O que se esconde dentro da armadura é um mistério total.'),
(206, 'Dunsparce', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/206.png', 'Quando avistado, este POKéMON escapa para trás perfurando furiosamente o chão com sua cauda.'),
(207, 'Gligar', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/207.png', 'Ele voa direto para o rosto do alvo e então ataca a vítima assustada para injetar veneno.'),
(208, 'Steelix', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/208.png', 'Seu corpo foi comprimido profundamente sob o solo. Como resultado, é ainda mais duro que um diamante.'),
(209, 'Snubbull', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/209.png', 'Embora pareça assustador, na verdade é gentil e afetuoso. É muito popular entre as mulheres.'),
(210, 'Granbull', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/210.png', 'Na verdade, é tímido e se assusta facilmente. Se for atacado, ele se debate para se defender do atacante.'),
(211, 'Qwilfish', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/211.png', 'Para disparar seus espinhos venenosos, ele deve inflar seu corpo bebendo mais de 2,6 galões de água de uma só vez.'),
(212, 'Scizor', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/212.png', 'Ele balança suas pinças com padrões oculares para assustar seus inimigos. Isso faz com que pareça que tem três cabeças.'),
(213, 'Shuckle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/213.png', 'As BAGAS que ele armazena em sua concha em forma de vaso se decompõem e se tornam um líquido pegajoso.'),
(214, 'Heracross', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/214.png', 'Este poderoso POKéMON enfia seu valioso chifre sob a barriga dos inimigos, depois os levanta e arremessa.'),
(215, 'Sneasel', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/215.png', 'Suas patas escondem garras afiadas. Se for atacado, ele repentinamente estende as garras e assusta o inimigo.'),
(216, 'Teddiursa', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/216.png', 'Se encontrar mel, sua marca crescente brilha. Ele sempre lambe as patas porque estão encharcadas de mel.'),
(217, 'Ursaring', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/217.png', 'Embora seja um bom escalador, prefere quebrar árvores com as patas dianteiras e comer BAGAS caídas.'),
(218, 'Slugma', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/218.png', 'Nunca dorme. Ele tem que continuar se movendo porque se parasse, seu corpo de magma esfriaria e endureceria.'),
(219, 'Magcargo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/219.png', 'A casca nas costas é apenas pele que esfriou e endureceu. Quebra facilmente com um leve toque.'),
(220, 'Swinub', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/220.png', 'Ele esfrega o focinho no chão para encontrar e desenterrar comida. Às vezes descobre fontes termais.'),
(221, 'Piloswine', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/221.png', 'Como o cabelo comprido por todo o corpo obscurece sua visão, ele continua carregando repetidamente.'),
(222, 'Corsola', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/222.png', 'Ele continuamente se desprende e cresce. A ponta de sua cabeça é considerada um tesouro por sua beleza.'),
(223, 'Remoraid', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/223.png', 'Tem uma precisão excelente. A água que ele lança pode atingir até mesmo presas em movimento a mais de 90 metros de distância.'),
(224, 'Octillery', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/224.png', 'Ele prende os inimigos com seus tentáculos com ventosas e depois os esmaga com sua cabeça dura como pedra.'),
(225, 'Delibird', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/225.png', 'Ele carrega comida o dia todo. Existem histórias sobre pessoas perdidas que foram salvas pela comida que tinham.'),
(226, 'Mantine', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/226.png', 'Enquanto nada majestosamente, ele não se importa se REMORAID se prende a ele para limpar seus restos.'),
(227, 'Skarmory', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/227.png', 'Suas asas robustas parecem pesadas, mas na verdade são ocas e leves, permitindo-lhe voar livremente no céu.'),
(228, 'Houndour', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/228.png', 'Ele usa diferentes tipos de gritos para se comunicar com outros de sua espécie e para perseguir suas presas.'),
(229, 'Houndoom', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/229.png', 'Se você for queimado pelas chamas que sai de sua boca, a dor nunca irá embora.'),
(230, 'Kingdra', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/230.png', 'Diz-se que geralmente se esconde em cavernas subaquáticas. Ele pode criar redemoinhos ao bocejar.'),
(231, 'Phanpy', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/231.png', 'Ele balança seu longo focinho para brincar, mas por ser tão forte, isso pode ser perigoso.'),
(232, 'Donphan', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/232.png', 'Possui presas afiadas e duras e uma pele robusta. Seu TACKLE é forte o suficiente para derrubar uma casa.'),
(233, 'Porygon2', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/233.png', 'Esta versão atualizada do PORYGON foi projetada para exploração espacial. Mas não pode voar.'),
(234, 'Stantler', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/234.png', 'Os chifres curvos alteram sutilmente o fluxo de ar para criar um espaço estranho onde a realidade é distorcida.'),
(235, 'Smeargle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/235.png', 'Um fluido especial escorre da ponta da cauda. Pinta o fluido por toda parte para marcar seu território.'),
(236, 'Tyrogue', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/236.png', 'Está sempre cheio de energia. Para se fortalecer, continua lutando mesmo quando perde.'),
(237, 'Hitmontop', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/237.png', 'Se você ficar encantado com seus chutes suaves, elegantes e dançantes, poderá se exercitar muito.'),
(238, 'Smoochum', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/238.png', 'Seus lábios são as partes mais sensíveis do corpo. Ele sempre usa os lábios primeiro para examinar as coisas.'),
(239, 'Elekid', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/239.png', 'Ele gira os braços para gerar eletricidade, mas cansa-se facilmente, por isso carrega apenas um pouco.'),
(240, 'Magby', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/240.png', 'Cada vez que inspira e expira, brasas quentes escorrem de sua boca e narinas.'),
(241, 'Miltank', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/241.png', 'Seu leite é repleto de nutrientes, tornando-o a bebida definitiva para os doentes ou cansados.'),
(242, 'Blissey', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/242.png', 'Qualquer um que dê uma só mordida no ovo de BLISSEY se torna infalivelmente atencioso e agradável com todos.'),
(243, 'Raikou', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/243.png', 'As nuvens de chuva que ele carrega permitem que ele dispare raios à vontade. Dizem que desceu com um raio.'),
(244, 'Entei', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/244.png', 'Vulcões entram em erupção quando ele late. Incapaz de conter seu poder extremo, ele corre precipitadamente pela terra.'),
(245, 'Suicune', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/245.png', 'Considerado a reencarnação dos ventos do norte, pode purificar instantaneamente a água suja e turva.'),
(246, 'Larvitar', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/246.png', 'Alimenta-se de solo. Depois de ter comido uma grande montanha, ele adormecerá para poder crescer.'),
(247, 'Pupitar', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/247.png', 'Sua concha é tão dura quanto uma rocha e também muito forte. Sua surra pode derrubar uma montanha.'),
(248, 'Tyranitar', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/248.png', 'Seu corpo não pode ser ferido por nenhum tipo de ataque, por isso está muito ansioso para fazer desafios contra os inimigos.'),
(249, 'Lugia', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/249.png', 'Diz-se que ele passa o tempo silenciosamente no fundo do mar porque seus poderes são muito fortes.'),
(250, 'Ho-oh', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/250.png', 'As lendas afirmam que este POKéMON voa continuamente pelos céus do mundo em suas magníficas asas de sete cores.'),
(251, 'Celebi', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/251.png', 'Este POKéMON vagueia no tempo. A grama e as árvores florescem nas florestas em que aparecem.'),
(252, 'Treecko', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/252.png', 'TREECKO possui pequenos ganchos na planta dos pés que lhe permitem escalar paredes verticais. Este POKéMON ataca atacando os inimigos com sua cauda grossa.'),
(253, 'Grovyle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/253.png', 'As folhas que crescem no corpo de GROVYLE são convenientes para camuflá-lo dos inimigos na floresta. Este POKéMON é um mestre em subir em árvores na selva.'),
(254, 'Sceptile', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/254.png', 'As folhas que crescem no corpo do SCEPTILE têm bordas muito afiadas. Este POKéMON é muito ágil - ele salta sobre os galhos das árvores e salta sobre o inimigo por cima ou por trás.'),
(255, 'Torchic', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/255.png', 'TORCHIC segue com seu TRAINER, seguindo atrás com passos instáveis. Este POKéMON cospe fogo a mais de 1.800 graus F, incluindo bolas de fogo que deixam o inimigo queimado de preto.'),
(256, 'Combusken', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/256.png', 'COMBUSKEN fortalece pernas e coxas correndo por campos e montanhas. As pernas deste POKéMON possuem velocidade e força, permitindo-lhe dar dez chutes em um segundo.'),
(257, 'Blaziken', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/257.png', 'Na batalha, BLAZIKEN solta chamas intensas de seus pulsos e ataca os inimigos com coragem. Quanto mais forte o inimigo, mais intensamente os pulsos deste POKéMON queimam.'),
(258, 'Mudkip', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/258.png', 'A barbatana na cabeça do MUDKIP atua como um radar altamente sensível. Usando esta barbatana para sentir os movimentos da água e do ar, este POKéMON pode determinar o que está acontecendo ao seu redor sem usar os olhos.'),
(259, 'Marshtomp', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/259.png', 'A superfície do corpo do MARSHTOMP é envolvida por uma película fina e pegajosa que lhe permite viver na terra. Este POKéMON brinca na lama das praias quando a maré está baixa.'),
(260, 'Swampert', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/260.png', 'SWAMPERT é muito forte. Tem potência suficiente para arrastar facilmente uma pedra pesando mais de uma tonelada. Este POKéMON também possui uma visão poderosa que lhe permite enxergar mesmo em águas turvas.'),
(261, 'Poochyena', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/261.png', 'À primeira vista, POOCHYENA dá uma mordida em qualquer coisa que se mova. Este POKéMON persegue a presa até que a vítima fique exausta. No entanto, ele pode virar o rabo se a presa contra-atacar.'),
(262, 'Mightyena', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/262.png', 'MIGHTYENA dá sinais óbvios quando se prepara para atacar. Ele começa a rosnar profundamente e depois achata o corpo. Este POKéMON morderá selvagemente com suas presas pontiagudas.'),
(263, 'Zigzagoon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/263.png', 'ZIGZAGOON vagueia incansavelmente por toda parte o tempo todo. Este POKéMON faz isso porque é muito curioso. Ele se interessa por tudo o que vê.'),
(264, 'Linoone', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/264.png', 'LINOONE sempre corre a toda velocidade e apenas em linha reta. Se estiver enfrentando um obstáculo, ele faz uma curva em ângulo reto para evitá-lo. Este POKéMON é muito desafiado por estradas com curvas suaves.'),
(265, 'Wurmple', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/265.png', 'Usando os espinhos na parte traseira, o WURMPLE descasca a casca das árvores e se alimenta da seiva que escorre. Os pés deste POKéMON possuem ventosas que permitem que ele se agarre ao vidro sem escorregar.'),
(266, 'Silcoon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/266.png', 'SILCOON se amarra a um galho de árvore usando seda para não cair. Lá, este POKéMON fica quieto enquanto aguarda a evolução. Ele sai do casulo de seda através de um pequeno buraco.'),
(267, 'Beautifly', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/267.png', 'A comida favorita de BEAUTIFLY é o doce pólen das flores. Se você quiser ver esse POKéMON, basta deixar um vaso de flor perto de uma janela aberta. BEAUTIFLY certamente virá em busca de pólen.'),
(268, 'Cascoon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/268.png', 'CASCOON faz seu casulo protetor envolvendo seu corpo inteiramente com uma seda fina que sai de sua boca. Depois que a seda envolve seu corpo, ela endurece. Este POKéMON se prepara para sua evolução dentro do casulo.'),
(269, 'Dustox', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/269.png', 'DUSTOX é instintivamente atraído pela luz. Enxames deste POKéMON são atraídos pelas luzes brilhantes das cidades, onde causam estragos ao arrancar as folhas das árvores à beira das estradas para se alimentar.'),
(270, 'Lotad', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/270.png', 'LOTAD vivem em lagoas e lagos, onde flutuam na superfície. Ela fica fraca se sua folha larga morrer. Em raras ocasiões, este POKéMON viaja por terra em busca de água limpa.'),
(271, 'Lombre', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/271.png', 'LOMBRE é noturno - ficará ativo após o anoitecer. É também um criador de travessuras. Quando este POKéMON avista pescadores, ele puxa suas linhas de pesca abaixo da superfície e fica consternado.'),
(272, 'Ludicolo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/272.png', 'LUDICOLO começa a dançar assim que ouve uma música alegre e festiva. Diz-se que este POKéMON aparece quando ouve o canto de crianças em caminhadas.'),
(273, 'Seedot', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/273.png', 'SEEDOT se prende a um galho de árvore usando o topo de sua cabeça. Ele suga a umidade da árvore enquanto está pendurado no galho. Quanto mais água ele bebe, mais brilhante fica o corpo do POKéMON.'),
(274, 'Nuzleaf', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/274.png', 'NUZLEAF vivem em florestas densamente cobertas de vegetação. Ocasionalmente, eles se aventuram fora da floresta para assustar as pessoas. Este POKéMON não gosta de ter seu nariz comprido comprimido.'),
(275, 'Shiftry', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/275.png', 'SHIFTRY é um POKéMON misterioso que supostamente vive no topo de árvores imponentes que datam de mais de mil anos. Ele cria tempestades de vento incríveis com os ventiladores que contém.'),
(276, 'Taillow', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/276.png', 'TAILLOW corajosamente mantém sua posição contra os inimigos, por mais fortes que sejam. Este corajoso POKéMON permanecerá desafiador mesmo após uma derrota. Por outro lado, chora alto se fica com fome.'),
(277, 'Swellow', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/277.png', 'SWELLOW voa bem acima de nossas cabeças, formando arcos graciosos no céu. Este POKéMON mergulha em um ângulo acentuado assim que avista sua presa. A infeliz presa é firmemente agarrada pelas garras do SWELLOW, impedindo a fuga.'),
(278, 'Wingull', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/278.png', 'WINGULL tem o hábito de carregar presas e objetos de valor em seu bico e escondê-los em todos os tipos de locais. Este POKéMON cavalga os ventos e voa como se estivesse patinando no céu.'),
(279, 'Pelipper', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/279.png', 'PELIPPER é um transportador voador que carrega pequenos POKéMON e ovos dentro de seu enorme bico. Este POKéMON constrói seu ninho em falésias íngremes de frente para o mar.'),
(280, 'Ralts', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/280.png', 'O RALTS sente as emoções das pessoas usando os chifres na sua cabeça. Este POKéMON raramente aparece diante das pessoas. Mas quando isso acontece, aproxima-se se sentir que a pessoa tem uma disposição positiva.'),
(281, 'Kirlia', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/281.png', 'Diz-se que uma KIRLIA que é exposta às emoções positivas do seu TREINADOR fica linda. Este POKéMON controla poderes psicocinéticos com seu cérebro altamente desenvolvido.'),
(282, 'Gardevoir', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/282.png', 'GARDEVOIR tem a capacidade de ler o futuro. Se sentir um perigo iminente para o seu TREINADOR, diz-se que este POKéMON liberta a sua energia psicocinética com força total.'),
(283, 'Surskit', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/283.png', 'Da ponta dos pés, o SURSKIT secreta um óleo que lhe permite andar sobre a água como se estivesse patinando. Este POKéMON se alimenta de organismos microscópicos em lagoas e lagos.'),
(284, 'Masquerain', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/284.png', 'MASQUERAIN intimida os inimigos com padrões semelhantes a olhos em suas antenas. Este POKéMON bate suas quatro asas para voar livremente em qualquer direção – até mesmo para os lados e para trás – como se fosse um helicóptero.'),
(285, 'Shroomish', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/285.png', 'SHROOMISH vivem em solo úmido nas profundezas escuras das florestas. Eles são freqüentemente encontrados parados sob as folhas caídas. Este POKéMON se alimenta de composto feito de folhas caídas e podres.'),
(286, 'Breloom', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/286.png', 'BRELOOM se aproxima de seu inimigo com movimentos de pés leves e ágeis, depois dá socos com seus braços elásticos. A técnica de luta deste POKéMON envergonha os boxeadores.'),
(287, 'Slakoth', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/287.png', 'SLAKOTH fica parado por mais de vinte horas todos os dias. Por se mover tão pouco, não precisa de muita comida. A única refeição diária deste POKéMON consiste em apenas três folhas.'),
(288, 'Vigoroth', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/288.png', 'VIGOROTH está sempre ansioso e agitado para entrar em fúria selvagem. Ele simplesmente não consegue tolerar ficar parado nem por um minuto. O nível de estresse deste POKéMON aumenta se ele não puder se mover constantemente.'),
(289, 'Slaking', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/289.png', 'SLAKING passa o dia todo deitado e descansando. Ele come grama que cresce ao seu alcance. Se comer toda a grama que puder alcançar, este POKéMON se moverá relutantemente para outro local.'),
(290, 'Nincada', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/290.png', 'NINCADA vive no subsolo há muitos anos em completa escuridão. Este POKéMON absorve nutrientes das raízes das árvores. Ele permanece imóvel enquanto espera pela evolução.'),
(291, 'Ninjask', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/291.png', 'NINJASK se move a uma velocidade tão alta que não pode ser visto, mesmo quando seu choro pode ser ouvido claramente. Por essa razão, durante muito tempo acreditou-se que este POKéMON era invisível.'),
(292, 'Shedinja', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/292.png', 'O corpo rígido de SHEDINJA não se move – nem mesmo uma contração. Na verdade, seu corpo parece ser apenas uma concha oca. Acredita-se que este POKéMON roubará o espírito de qualquer um que espie seu corpo oco pelas costas.'),
(293, 'Whismur', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/293.png', 'Normalmente, a voz de WHISMUR é muito baixa – quase não é audível, mesmo se alguém estiver prestando muita atenção. Porém, se este POKéMON sentir perigo, ele começa a chorar em um volume ensurdecedor.'),
(294, 'Loudred', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/294.png', 'Os gritos do LOUDRED podem dizimar completamente uma casa de madeira. Ele usa sua voz para punir seus inimigos. As orelhas redondas deste POKéMON servem como alto-falantes.'),
(295, 'Exploud', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/295.png', 'EXPLOUD desencadeia terremotos com os tremores que cria ao gritar. Se este POKéMON inala violentamente pelas portas de seu corpo, é um sinal de que ele está se preparando para soltar um enorme grito.'),
(296, 'Makuhita', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/296.png', 'MAKUHITA é tenaz – ele continuará se levantando e atacando seu inimigo quantas vezes for derrubado. Cada vez que se levanta, este POKéMON armazena mais energia em seu corpo para evoluir.'),
(297, 'Hariyama', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/297.png', 'HARIYAMA pratica seus tapas com os braços esticados em vários locais. Um golpe dos socos poderosos, de mão aberta e de braço reto deste POKéMON poderia quebrar um poste telefônico em dois.'),
(298, 'Azurill', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/298.png', 'AZURILL gira a cauda como se fosse um laço e depois a arremessa para longe. O impulso do lançamento também faz seu corpo voar. Usando esta ação única, um desses POKéMON conseguiu lançar-se a uma altura recorde de 33 pés.'),
(299, 'Nosepass', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/299.png', 'O nariz magnético do NOSEPASS está sempre apontado para o norte. Se dois desses POKéMON se encontrarem, eles não poderão virar o rosto um para o outro quando estiverem próximos porque seus narizes magnéticos se repelem.'),
(300, 'Skitty', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/300.png', 'SKITTY tem o hábito de ficar fascinado por objetos em movimento e persegui-los. Este POKéMON é conhecido por perseguir o próprio rabo e ficar tonto.'),
(301, 'Delcatty', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/301.png', 'DELCATTY prefere viver uma existência livre, na qual possa fazer o que quiser no seu próprio ritmo. Como este POKéMON come e dorme quando quer, suas rotinas diárias são completamente aleatórias.'),
(302, 'Sableye', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/302.png', 'SABLEYE levam vidas tranquilas nas profundezas das cavernas. Eles são temidos, no entanto, porque acredita-se que esses POKéMON roubam os espíritos das pessoas quando seus olhos queimam com um brilho sinistro na escuridão.'),
(303, 'Mawile', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/303.png', 'As enormes mandíbulas de MAWHILE são na verdade chifres de aço que foram transformados. Seu rosto de aparência dócil serve para acalmar seu inimigo e fazê-lo baixar a guarda. Quando o inimigo menos espera, MAWHILE o morde com suas mandíbulas abertas.'),
(304, 'Aron', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/304.png', 'Este POKéMON tem um corpo de aço. Para fazer seu corpo, ARON se alimenta de minério de ferro que extrai das montanhas. Ocasionalmente, causa grandes problemas ao comer pontes e trilhos.'),
(305, 'Lairon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/305.png', 'LAIRON tempera seu corpo de aço bebendo água mineral altamente nutritiva até ficar inchado. Este POKéMON faz seu ninho perto de fontes de águas deliciosas.'),
(306, 'Aggron', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/306.png', 'AGGRON reivindica uma montanha inteira como seu próprio território. Ele bate impiedosamente em qualquer coisa que viole seu ambiente. Este POKéMON patrulha vigilantemente seu território o tempo todo.'),
(307, 'Meditite', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/307.png', 'MEDITITE realiza um treinamento mental rigoroso nas profundezas das montanhas. Porém, sempre que medita, este POKéMON sempre perde a concentração e o foco. Como resultado, o seu treinamento nunca termina.'),
(308, 'Medicham', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/308.png', 'Diz-se que através da meditação, MEDICHAM aumenta a energia dentro do seu corpo e aguça o seu sexto sentido. Este POKéMON esconde a sua presença fundindo-se com campos e montanhas.'),
(309, 'Electrike', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/309.png', 'ELECTRIKE armazena eletricidade em seus longos pelos corporais. Este POKéMON estimula os músculos das pernas com cargas elétricas. Esses choques de força proporcionam às suas pernas um desempenho de aceleração explosivo.'),
(310, 'Manectric', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/310.png', 'MANECTRIC está constantemente descarregando eletricidade de sua crina. As faíscas às vezes provocam incêndios florestais. Quando entra em uma batalha, este POKéMON cria nuvens de tempestade.'),
(311, 'Plusle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/311.png', 'A PLUSLE sempre atua como uma líder de torcida para seus parceiros. Sempre que um companheiro de equipe faz um bom esforço na batalha, este POKéMON encurta seu corpo para criar ruídos crepitantes de faíscas para mostrar sua alegria.'),
(312, 'Minun', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/312.png', 'O MINUN está mais preocupado em torcer pelos seus parceiros do que pela sua própria segurança. Ele interrompe a eletricidade em seu corpo para criar chuvas brilhantes de faíscas para torcer por seus companheiros de equipe.'),
(313, 'Volbeat', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/313.png', 'Com a chegada da noite, o VOLBEAT emite luz pela cauda. Ele se comunica com outras pessoas ajustando a intensidade e o brilho de sua luz. Este POKéMON é atraído pelo doce aroma de ILLUMISE.'),
(314, 'Illumise', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/314.png', 'ILLUMISE atrai um enxame de VOLBEAT usando uma fragrância doce. Uma vez reunidos os VOLBEAT, este POKéMON lidera o enxame iluminado desenhando desenhos geométricos na tela do céu noturno.'),
(315, 'Roselia', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/315.png', 'ROSELIA atira espinhos afiados como projéteis em qualquer oponente que tente roubar as flores de seus braços. O aroma deste POKéMON traz serenidade aos seres vivos.'),
(316, 'Gulpin', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/316.png', 'Praticamente todo o corpo do GULPIN é estômago. Como resultado, ele pode engolir algo do seu tamanho. O estômago deste POKéMON contém um fluido especial que digere qualquer coisa.'),
(317, 'Swalot', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/317.png', 'Quando o SWALOT avista uma presa, ele expele um fluido terrivelmente tóxico pelos poros e borrifa o alvo. Assim que a presa enfraquece, este POKéMON a engole inteira com sua boca cavernosa.'),
(318, 'Carvanha', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/318.png', 'As mandíbulas fortemente desenvolvidas da CARVANHA e as suas presas pontiagudas possuem o poder destrutivo para arrancar cascos de barcos. Muitos barcos foram atacados e afundados por este POKéMON.'),
(319, 'Sharpedo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/319.png', 'Apelidado de “o valentão do mar”, SHARPEDO é amplamente temido. Suas presas cruéis voltam a crescer imediatamente quando se quebram. Apenas um desses POKéMON pode destruir completamente um superpetroleiro.'),
(320, 'Wailmer', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/320.png', 'As narinas de WAILMER estão localizadas acima dos olhos. Este POKéMON brincalhão adora assustar as pessoas cheirando com força a água do mar que armazena dentro de seu corpo, saindo pelas narinas.'),
(321, 'Wailord', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/321.png', 'WAILORD é o maior de todos os POKéMON identificados até agora. Este POKéMON gigante nada languidamente no vasto mar aberto, comendo grandes quantidades de comida de uma só vez com sua boca enorme.'),
(322, 'Numel', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/322.png', 'NUMEL é extremamente estúpido - não percebe ser atingido. No entanto, não suporta a fome nem por um segundo. O corpo deste POKéMON é um caldeirão fervente de magma fervente.'),
(323, 'Camerupt', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/323.png', 'CAMERUPT tem um vulcão dentro de seu corpo. Magma de 18.000 graus F percorre seu corpo. Ocasionalmente, as saliências nas costas deste POKéMON explodem, expelindo o magma superaquecido.'),
(324, 'Torkoal', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/324.png', 'TORKOAL escava montanhas em busca de carvão. Se encontrar algum, preenche os espaços vazios da sua concha com o carvão e queima-o. Se for atacado, este POKéMON solta uma espessa fumaça preta para bater em retirada.'),
(325, 'Spoink', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/325.png', 'SPOINK salta na cauda. O choque de seu salto faz seu coração bater mais forte. Como resultado, este POKéMON não pode parar de saltar - se parar, o seu coração irá parar.'),
(326, 'Grumpig', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/326.png', 'GRUMPIG usa as pérolas negras em seu corpo para amplificar suas ondas de poder psíquico e obter controle total sobre seu inimigo. Quando este POKéMON usa seu poder especial, sua respiração bufante fica difícil.'),
(327, 'Spinda', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/327.png', 'Diz-se que todos os SPINDA que existem no mundo têm padrões de manchas totalmente únicos. Os passos trêmulos e cambaleantes deste POKéMON dão-lhe a aparência de dançar.'),
(328, 'Trapinch', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/328.png', 'O ninho do TRAPINCH é um poço inclinado em forma de tigela escavado na areia. Este POKéMON espera pacientemente que a presa caia no buraco. Suas mandíbulas gigantes têm força suficiente para esmagar até pedras.'),
(329, 'Vibrava', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/329.png', 'Para fazer a presa desmaiar, o VIBRAVA gera ondas ultrassônicas fazendo vibrar vigorosamente suas duas asas. As ondas ultrassônicas deste POKéMON são tão poderosas que podem causar dores de cabeça nas pessoas.'),
(330, 'Flygon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/330.png', 'FLYGON é apelidado de “o espírito elemental do deserto”. Como seu bater de asas levanta uma nuvem de areia, este POKéMON é sempre envolvido por uma tempestade de areia enquanto voa.'),
(331, 'Cacnea', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/331.png', 'CACNEA vive em locais áridos, como desertos. Libera um forte aroma de sua flor para atrair as presas. Quando a presa se aproxima, este POKéMON atira espinhos afiados de seu corpo para derrubar a vítima.'),
(332, 'Cacturne', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/332.png', 'Durante o dia, CACTURNE permanece imóvel para não perder umidade com o forte sol do deserto. Este POKéMON fica ativo à noite quando a temperatura cai.'),
(333, 'Swablu', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/333.png', 'SWABLU tem asas leves e fofas que parecem nuvens de algodão. Este POKéMON não tem medo das pessoas. Ele pousa na cabeça das pessoas e fica ali como um chapéu de algodão.'),
(334, 'Altaria', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/334.png', 'ALTARIA dança e gira pelo céu entre nuvens ondulantes, parecidas com algodão. Ao cantar melodias com sua voz cristalina, este POKéMON faz com que seus ouvintes experimentem uma maravilha sonhadora.'),
(335, 'Zangoose', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/335.png', 'Memórias da batalha contra seu arquirrival SEVIPER estão gravadas em cada célula do corpo de ZANGOOSE. Este POKéMON esquiva-se habilmente de ataques com uma agilidade incrível.'),
(336, 'Seviper', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/336.png', 'SEVIPER compartilha uma rivalidade de gerações com ZANGOOSE. As cicatrizes em seu corpo são evidências de batalhas cruéis. Este POKéMON ataca usando sua cauda afiada.'),
(337, 'Lunatone', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/337.png', 'LUNATONE foi descoberto em um local onde um meteorito caiu. Como resultado, algumas pessoas teorizam que este POKéMON veio do espaço. No entanto, ninguém foi capaz de provar esta teoria até agora.'),
(338, 'Solrock', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/338.png', 'SOLROCK é uma nova espécie de POKéMON que supostamente caiu do espaço. Ele flutua no ar e se move silenciosamente. Na batalha, este POKéMON libera luz intensamente brilhante.'),
(339, 'Barboach', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/339.png', 'Os bigodes sensíveis do BARBOACH servem como um excelente sistema de radar. Este POKéMON se esconde na lama, deixando apenas seus dois bigodes expostos enquanto espera a chegada da presa.'),
(340, 'Whiscash', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/340.png', 'WHISCASH é extremamente territorial. Apenas um desses POKéMON reivindicará um grande lago como seu território exclusivo. Se um inimigo se aproximar dele, ele se debaterá e desencadeará um grande terremoto.'),
(341, 'Corphish', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/341.png', 'CORPHISH eram originalmente POKéMON estrangeiros importados como animais de estimação. Eles finalmente apareceram na natureza. Este POKéMON é muito resistente e aumentou muito a sua população.'),
(342, 'Crawdaunt', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/342.png', 'CRAWDAUNT tem uma natureza extremamente violenta que o obriga a desafiar outros seres vivos para a batalha. Outras formas de vida se recusam a viver em lagoas habitadas por este POKéMON, tornando-as lugares desolados.'),
(343, 'Baltoy', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/343.png', 'BALTOY se move enquanto gira em um pé só. Pinturas murais primitivas representando este POKéMON vivendo entre as pessoas foram descobertas em algumas ruínas antigas.'),
(344, 'Claydol', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/344.png', 'Dizem que CLAYDOL são bonecos de lama feitos por humanos primitivos e trazidos à vida pela exposição a um raio misterioso. Este POKéMON se move enquanto levita.'),
(345, 'Lileep', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/345.png', 'LILEEP foi extinto há aproximadamente cem milhões de anos. Este antigo POKéMON se prende a uma rocha no fundo do mar e captura as presas que se aproximam usando tentáculos em forma de pétalas de flores.'),
(346, 'Cradily', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/346.png', 'CRADILY vagueia pelo fundo do oceano em busca de comida. Este POKéMON estende livremente seu pescoço em forma de tronco de árvore e captura presas incautas usando seus oito tentáculos.'),
(347, 'Anorith', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/347.png', 'ANORITH foi regenerado a partir de um fóssil pré-histórico. Este POKéMON primitivo já viveu em mares quentes. Ele agarra sua presa firmemente entre suas duas grandes garras.'),
(348, 'Armaldo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/348.png', 'A armadura resistente de ARMALDO faz com que todos os ataques sejam rebatidos. As duas enormes garras deste POKéMON podem ser estendidas ou contraídas livremente. Eles têm o poder de perfurar uma placa de aço.'),
(349, 'Feebas', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/349.png', 'As nadadeiras do FEEBAS estão esfarrapadas e esfarrapadas desde o início de sua vida. Devido à sua aparência de má qualidade, este POKéMON é amplamente ignorado. É capaz de viver tanto no mar como nos rios.'),
(350, 'Milotic', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/350.png', 'Dizem que MILOTIC é o mais bonito de todos os POKéMON. Tem o poder de acalmar emoções como raiva e hostilidade para acabar com rixas amargas.'),
(351, 'Castform', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/351.png', 'A aparência do CASTFORM muda com o clima. Este POKéMON ganhou a habilidade de usar o vasto poder da natureza para proteger seu minúsculo corpo.'),
(352, 'Kecleon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/352.png', 'KECLEON é capaz de mudar as cores do seu corpo à vontade para se misturar com o ambiente. Há uma exceção: este POKéMON não pode alterar o padrão em zigue-zague em sua barriga.'),
(353, 'Shuppet', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/353.png', 'SHUPPET é atraído por sentimentos de ciúme e vingança. Se alguém desenvolver fortes sentimentos de vingança, este POKéMON aparecerá em um enxame e se alinhará sob os beirais da casa dessa pessoa.'),
(354, 'Banette', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/354.png', 'BANETTE gera energia para lançar maldições fortes enfiando alfinetes em seu próprio corpo. Este POKéMON era originalmente um boneco de pelúcia lamentável que foi jogado fora.'),
(355, 'Duskull', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/355.png', 'DUSKULL pode atravessar qualquer parede, por mais espessa que seja. Assim que este POKéMON escolher um alvo, ele perseguirá obstinadamente a vítima pretendida até o amanhecer.'),
(356, 'Dusclops', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/356.png', 'O corpo de DUSCLOPS é completamente oco - não há nada dentro. Diz-se que seu corpo é como um buraco negro. Este POKéMON absorverá qualquer coisa em seu corpo, mas nada retornará.'),
(357, 'Tropius', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/357.png', 'Os cachos de frutas em volta do pescoço do TROPIUS são muito apreciados pelas crianças. Este POKéMON adora frutas e as come continuamente. Aparentemente, seu amor pelas frutas resultou em seu próprio crescimento de frutas.'),
(358, 'Chimecho', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/358.png', 'CHIMECHO faz seus gritos ecoarem dentro de seu corpo oco. Quando este POKéMON fica furioso, seus gritos resultam em ondas ultrassônicas que têm o poder de derrubar inimigos voando.'),
(359, 'Absol', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/359.png', 'Cada vez que a ABSOL aparece diante das pessoas, ela é seguida por um desastre, como um terremoto ou um maremoto. Como resultado, ficou conhecido como o desastre POKéMON.'),
(360, 'Wynaut', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/360.png', 'WYNAUT sempre pode ser visto com um grande e feliz sorriso no rosto. Olhe para a cauda para determinar se ele está com raiva. Quando irritado, este POKéMON estará batendo no chão com a cauda.'),
(361, 'Snorunt', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/361.png', 'SNORUNT vivem em regiões com fortes nevascas. Nas estações sem neve, como a primavera e o verão, este POKéMON foge para viver tranquilamente entre estalactites e estalagmites nas profundezas de cavernas.'),
(362, 'Glalie', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/362.png', 'GLALIE tem um corpo feito de rocha, que endurece com uma armadura de gelo. Este POKéMON tem a capacidade de congelar a umidade da atmosfera em qualquer forma que desejar.'),
(363, 'Spheal', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/363.png', 'SPHEAL rola muito mais rápido do que andar para se locomover. Quando grupos deste POKéMON comem, todos batem palmas ao mesmo tempo para demonstrar seu prazer. Por causa disso, a hora das refeições é barulhenta.'),
(364, 'Sealeo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/364.png', 'SEALEO tem o hábito de sempre fazer malabarismos na ponta do nariz com tudo o que vê pela primeira vez. Este POKéMON ocasionalmente se diverte equilibrando e rolando um SPHEAL no nariz.'),
(365, 'Walrein', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/365.png', 'As duas presas extremamente desenvolvidas de WALREIN podem quebrar totalmente blocos de gelo pesando dez toneladas com um só golpe. A espessa camada de gordura deste POKéMON o isola de temperaturas abaixo de zero.'),
(366, 'Clamperl', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/366.png', 'A carapaça robusta do CLAMPERL não é boa apenas para proteção - também é usada para prender e capturar presas. A casca de um CLAMPERL totalmente crescido ficará marcada com cortes e arranhões por toda parte.'),
(367, 'Huntail', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/367.png', 'A presença do HUNTAIL passou despercebida pelas pessoas por muito tempo porque ele vive em profundidades extremas no mar. Os olhos deste POKéMON podem ver claramente mesmo nas profundezas escuras do oceano.'),
(368, 'Gorebyss', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/368.png', 'GOREBYSS vive nos mares do sul, em profundidades extremas. Seu corpo foi construído para suportar a enorme pressão da água em profundidades incríveis. Por causa disso, o corpo deste POKéMON fica ileso de ataques comuns.'),
(369, 'Relicanth', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/369.png', 'RELICANTH é uma espécie de POKéMON que existiu por cem milhões de anos sem nunca mudar de forma. Este antigo POKéMON se alimenta de organismos microscópicos com sua boca desdentada.'),
(370, 'Luvdisc', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/370.png', 'LUVDISC vivem em mares rasos nos trópicos. Este POKéMON em forma de coração ganhou seu nome nadando atrás de casais apaixonados que avistou nas ondas do oceano.'),
(371, 'Bagon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/371.png', 'BAGON sonha um dia voar alto no céu. Num esforço frustrado para voar, este POKéMON se atira de penhascos. Como resultado dos mergulhos, sua cabeça ficou dura e dura como aço temperado.'),
(372, 'Shelgon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/372.png', 'Dentro da concha semelhante a uma armadura de SHELGON, as células estão no meio de uma transformação para criar um corpo inteiramente novo. A carapaça deste POKéMON é extremamente pesada, tornando seus movimentos lentos.'),
(373, 'Salamence', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/373.png', 'SALAMENCE surgiu como resultado de um sonho forte e antigo de criar asas. Diz-se que este desejo poderoso desencadeou uma mutação repentina nas células deste POKéMON, fazendo-lhe brotar as suas magníficas asas.'),
(374, 'Beldum', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/374.png', 'Em vez de sangue, uma poderosa força magnética percorre todo o corpo de BELDUM. Este POKéMON se comunica com outros enviando pulsos controlados de magnetismo.'),
(375, 'Metang', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/375.png', 'Quando dois BELDUM se fundem, forma-se METANG. Os cérebros do BELDUM são unidos por um sistema nervoso magnético. Ao conectar seus cérebros magneticamente, este POKéMON gera um forte poder psicocinético.'),
(376, 'Metagross', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/376.png', 'METAGROSS tem quatro cérebros no total. Combinados, os quatro cérebros podem realizar cálculos difíceis mais rapidamente do que um supercomputador. Este POKéMON pode flutuar no ar dobrando suas quatro pernas.'),
(377, 'Regirock', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/377.png', 'REGIROCK foi selado por pessoas há muito tempo. Se o corpo deste POKéMON for danificado em batalha, diz-se que ele procura pedras adequadas por conta própria para se reparar.'),
(378, 'Regice', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/378.png', 'O corpo de REGICE foi feito durante uma era glacial. O corpo ultracongelado não pode ser derretido, nem mesmo pelo fogo. Este POKéMON controla o ar gelado de 328 graus F negativos.'),
(379, 'Registeel', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/379.png', 'REGISTEEL possui um corpo mais duro que qualquer tipo de metal. Seu corpo é aparentemente oco. Ninguém tem ideia do que esse POKéMON come.'),
(380, 'Latias', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/380.png', 'LATIAS é altamente sensível às emoções das pessoas. Se sentir alguma hostilidade, este POKéMON agita as penas por todo o corpo e grita estridentemente para intimidar o inimigo.'),
(381, 'Latios', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/381.png', 'LATIOS tem a habilidade de fazer seu inimigo ver uma imagem daquilo que viu ou imaginou em sua cabeça. Este POKéMON é inteligente e entende a fala humana.'),
(382, 'Kyogre', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/382.png', 'KYOGRE tem o poder de criar enormes nuvens de chuva que cobrem todo o céu e provocam chuvas torrenciais. Este POKéMON salvou pessoas que sofriam com as secas.'),
(383, 'Groudon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/383.png', 'GROUDON há muito é descrito na mitologia como o POKéMON que ergueu terras e expandiu continentes. Este POKéMON adormeceu após uma batalha cataclísmica com KYOGRE.'),
(384, 'Rayquaza', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/384.png', 'RAYQUAZA viveu durante centenas de milhões de anos na camada de ozônio da Terra, nunca descendo ao solo. Este POKéMON parece se alimentar de água e partículas da atmosfera.'),
(385, 'Jirachi', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/385.png', 'Uma lenda afirma que JIRACHI realizará qualquer desejo que esteja escrito em notas presas à sua cabeça quando acordar. Se este POKéMON sentir perigo, ele lutará sem acordar.'),
(386, 'Deoxys-normal', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/386.png', 'O DNA de um vírus espacial sofreu uma mutação repentina após exposição a um raio laser e resultou em DEOXYS. O órgão cristalino no peito deste POKéMON parece ser o seu cérebro.'),
(387, 'Turtwig', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/387.png', 'Feita de terra, a concha nas costas endurece quando bebe água. Vive ao longo de lagos.'),
(388, 'Grotle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/388.png', 'Vive ao longo da água nas florestas. Durante o dia, sai da floresta para tomar sol em sua concha arborizada.'),
(389, 'Torterra', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/389.png', 'Ocasionalmente, pequenos Pokémon se reúnem em suas costas imóveis para começar a construir seus ninhos.'),
(390, 'Chimchar', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/390.png', 'Ele escala penhascos íngremes com agilidade para viver no topo de montanhas escarpadas. Seu fogo se apaga quando ele dorme.'),
(391, 'Monferno', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/391.png', 'Para intimidar os atacantes, ele estica o fogo na cauda para parecer maior.'),
(392, 'Infernape', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/392.png', 'Ele usa um tipo especial de artes marciais envolvendo todos os seus membros. Seu fogo nunca se apaga.'),
(393, 'Piplup', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/393.png', 'Por ser muito orgulhoso, odeia aceitar comida das pessoas. A sua penugem espessa protege-o do frio.'),
(394, 'Prinplup', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/394.png', 'Vive sozinho, longe dos outros. Aparentemente, cada um deles acredita que é o mais importante.'),
(395, 'Empoleon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/395.png', 'Os três chifres que se estendem do seu bico atestam o seu poder. O líder tem os chifres maiores.'),
(396, 'Starly', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/396.png', 'Eles se aglomeram em grande número. Embora pequenos, eles batem as asas com grande força.'),
(397, 'Staravia', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/397.png', 'Ele voa por florestas e campos em busca de Pokémon insetos. Permanece dentro de um rebanho enorme.'),
(398, 'Staraptor', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/398.png', 'Tem uma natureza selvagem. Desafiará corajosamente inimigos muito maiores.'),
(399, 'Bidoof', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/399.png', 'Com nervos de aço, nada pode perturbá-lo. É mais ágil e ativo do que parece.'),
(400, 'Bibarel', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/400.png', 'Faz seu ninho represando riachos com casca e lama. É conhecido como um trabalhador diligente.'),
(401, 'Kricketot', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/401.png', 'Ele balança a cabeça de trás para frente, fazendo com que suas antenas se choquem e soem como um xilofone.'),
(402, 'Kricketune', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/402.png', 'Ele cruza os braços em forma de faca na frente do peito quando chora. Pode compor melodias ad lib.'),
(403, 'Shinx', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/403.png', 'Todo o seu pelo deslumbra se o perigo for sentido. Ele foge enquanto o inimigo fica momentaneamente cego.'),
(404, 'Luxio', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/404.png', 'Suas garras soltam eletricidade com amperagem suficiente para causar desmaios. Eles vivem em pequenos grupos.'),
(405, 'Luxray', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/405.png', 'Tem olhos que podem ver através de qualquer coisa. Ele localiza e captura presas escondidas atrás de objetos.'),
(406, 'Budew', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/406.png', 'No inverno, fecha o botão e aguenta o frio. Na primavera, o botão se abre e libera pólen.'),
(407, 'Roserade', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/407.png', 'Atrai a presa com um aroma doce e depois abate-a com chicotes espinhosos escondidos nos braços.'),
(408, 'Cranidos', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/408.png', 'Ele viveu nas selvas há cerca de 100 milhões de anos. Seu crânio é duro como ferro.'),
(409, 'Rampardos', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/409.png', 'Sua poderosa cabeça tem poder suficiente para quebrar até mesmo as coisas mais duráveis ​​com o impacto.'),
(410, 'Shieldon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/410.png', 'Um Pokémon que viveu nas selvas há cerca de 100 milhões de anos. Sua pele facial é extremamente dura.'),
(411, 'Bastiodon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/411.png', 'Qualquer ataque frontal é repelido. É um Pokémon dócil que se alimenta de grama e frutas vermelhas.'),
(412, 'Burmy', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/412.png', 'Para se proteger dos ventos frios e invernais, cobre-se com um manto feito de galhos e folhas.'),
(413, 'Wormadam-plant', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/413.png', 'Quando BURMY evoluiu, a sua capa tornou-se parte do corpo deste Pokémon. A capa nunca é retirada.'),
(414, 'Mothim', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/414.png', 'Adora o mel das flores e rouba o mel recolhido pelo COMBEE.'),
(415, 'Combee', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/415.png', 'Um Pokémon formado por outros três. Transporta ativamente mel floral doce para VESPIQUEN.'),
(416, 'Vespiquen', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/416.png', 'Seu abdômen é um favo de mel para larvas. Cria suas larvas com mel coletado pelo COMBEE.'),
(417, 'Pachirisu', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/417.png', 'Faz bolas de pelo que estalam com eletricidade estática. Ele os armazena junto com frutas em buracos de árvores.'),
(418, 'Buizel', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/418.png', 'Possui um saco flutuante que lembra uma coleira inflável. Ele flutua na água com a cabeça para fora.'),
(419, 'Floatzel', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/419.png', 'Ele flutua usando seu saco de flutuação bem desenvolvido. Auxilia no resgate de pessoas que estão se afogando.'),
(420, 'Cherubi', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/420.png', 'A pequena bola contém os nutrientes necessários para a evolução. Aparentemente é muito doce e saboroso.'),
(421, 'Cherrim', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/421.png', 'Ela floresce em épocas de forte luz solar. Ele tenta compensar tudo o que suportou quando era um botão.'),
(422, 'Shellos', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/422.png', 'Suas cores e formas variam de região para região. Na região de Sinnoh, dois tipos estão confirmados.'),
(423, 'Gastrodon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/423.png', 'Tem um corpo flexível sem ossos. Se alguma parte do seu corpo for arrancada, ela volta a crescer.'),
(424, 'Ambipom', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/424.png', 'Para comer, ele descasca nozes habilmente com as duas caudas. Raramente usa os braços agora.'),
(425, 'Drifloon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/425.png', 'Um Pokémon formado pelos espíritos de pessoas e Pokémon. Adora estações úmidas e úmidas.'),
(426, 'Drifblim', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/426.png', 'É sonolento durante o dia, mas voa à noite em grandes grupos. Ninguém sabe para onde eles vão.'),
(427, 'Buneary', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/427.png', 'Ele ataca os inimigos desenrolando bruscamente suas orelhas enroladas. Dói o suficiente para fazer um adulto chorar de dor.'),
(428, 'Lopunny', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/428.png', 'Um Pokémon extremamente cauteloso. Ele cobre seu corpo com o pêlo fofo da orelha quando sente perigo.'),
(429, 'Mismagius', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/429.png', 'Seus gritos soam como encantamentos. Aqueles que ouvem são atormentados por dores de cabeça e alucinações.'),
(430, 'Honchkrow', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/430.png', 'Tornando-se ativo à noite, é conhecido por aglomerar numerosos MURKROW a reboque.'),
(431, 'Glameow', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/431.png', 'Ele arranha quando está descontente e ronrona quando é afetuoso. Sua inconstância é muito popular entre alguns.'),
(432, 'Purugly', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/432.png', 'É um bruto descarado que invade o ninho de outro Pokémon e o reivindica como seu.'),
(433, 'Chingling', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/433.png', 'Ele emite gritos agitando um orbe no fundo da garganta. Ele se move com saltos agitados.'),
(434, 'Stunky', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/434.png', 'Ele se protege pulverizando um fluido nocivo pela parte traseira. O fedor permanece por 24 horas.'),
(435, 'Skuntank', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/435.png', 'Ele borrifa um fluido de cheiro horrível da ponta da cauda para atacar. Seu alcance é superior a 160 pés.'),
(436, 'Bronzor', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/436.png', 'Implementos com esse formato foram descobertos em tumbas antigas. Não se sabe se eles estão relacionados.'),
(437, 'Bronzong', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/437.png', 'Um deles causou sensação quando foi desenterrado em um canteiro de obras após um sono de 2.000 anos.'),
(438, 'Bonsly', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/438.png', 'Parece que está sempre chorando. Na verdade, está ajustando os níveis de fluidos do corpo, eliminando o excesso.'),
(439, 'Mime-jr', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/439.png', 'Habitualmente imita os inimigos. Uma vez imitado, o inimigo não consegue tirar os olhos deste Pokémon.'),
(440, 'Happiny', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/440.png', 'Adora coisas brancas redondas. Carrega uma pedra em forma de ovo imitando CHANSEY.'),
(441, 'Chatot', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/441.png', 'Ele pode aprender e falar palavras humanas. Se eles se reunirem, todos aprenderão o mesmo ditado.'),
(442, 'Spiritomb', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/442.png', 'Um Pokémon formado por 108 espíritos. Está ligado a uma fissura em uma estranha pedra angular.'),
(443, 'Gible', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/443.png', 'Nidifica em pequenos buracos horizontais nas paredes das cavernas. Ele ataca para capturar presas que se aproximam demais.'),
(444, 'Gabite', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/444.png', 'Há uma crença antiga de que os remédios feitos a partir de suas escamas curam até doenças incuráveis.'),
(445, 'Garchomp', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/445.png', 'Quando dobra o corpo e estende as asas, parece um avião a jato. Ele voa em velocidade sônica.'),
(446, 'Munchlax', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/446.png', 'Ele devora seu peso em alimentos uma vez por dia, engolindo alimentos inteiros quase sem mastigar.'),
(447, 'Riolu', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/447.png', 'A aura que emana do seu corpo intensifica-se para alertar os outros caso esteja com medo ou triste.'),
(448, 'Lucario', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/448.png', 'Tem a capacidade de sentir a aura de todas as coisas. Ele entende a fala humana.'),
(449, 'Hippopotas', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/449.png', 'Vive em lugares áridos. Em vez de transpiração, expele areia granulada de seu corpo.'),
(450, 'Hippowdon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/450.png', 'Ele explode areia armazenada internamente nas portas de seu corpo para criar um tornado imponente para ataque.'),
(451, 'Skorupi', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/451.png', 'Ele agarra a presa com as garras da cauda e injeta veneno. Ele persiste tenazmente até que o veneno tome conta.'),
(452, 'Drapion', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/452.png', 'Ele tem em seus braços com garras o poder de transformar um carro em sucata. As pontas de suas garras liberam veneno.'),
(453, 'Croagunk', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/453.png', 'Suas bochechas contêm bolsas de veneno. Ele tenta pegar os inimigos desprevenidos e acertá-los com dedos tóxicos.'),
(454, 'Toxicroak', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/454.png', 'Suas garras secretam uma toxina tão vil que até mesmo um arranhão pode ser fatal.'),
(455, 'Carnivine', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/455.png', 'Ele atrai a presa com sua saliva de cheiro adocicado e depois a mastiga. Demora um dia inteiro para comer uma presa.'),
(456, 'Finneon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/456.png', 'Após longa exposição à luz solar, os padrões nas barbatanas da cauda brilham vividamente quando chega a escuridão.'),
(457, 'Lumineon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/457.png', 'Ele vive no fundo do mar. Ele atrai presas exibindo os padrões em suas quatro nadadeiras caudais.'),
(458, 'Mantyke', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/458.png', 'Um Pokémon amigável que captura os fluxos sutis da água do mar usando suas duas antenas.'),
(459, 'Snover', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/459.png', 'Vive em montanhas nevadas. Tendo tido pouco contato com humanos, é ousadamente curioso.'),
(460, 'Abomasnow', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/460.png', 'Provoca nevascas em montanhas que estão sempre enterradas na neve. É o abominável boneco de neve.'),
(461, 'Weavile', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/461.png', 'Vivem em regiões frias, formando grupos de quatro ou cinco que caçam presas com impressionante coordenação.'),
(462, 'Magnezone', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/462.png', 'Evoluiu da exposição a um campo magnético especial. Três unidades geram magnetismo.'),
(463, 'Lickilicky', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/463.png', 'Envolve as coisas com sua língua extensível. Chegar muito perto dele deixará você encharcado de baba.'),
(464, 'Rhyperior', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/464.png', 'Ele coloca pedras em buracos nas palmas das mãos e usa os músculos para atirar nelas. GEODUDE são baleados em raros momentos.'),
(465, 'Tangrowth', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/465.png', 'Ele captura a presa estendendo braços feitos de videiras. Perder armas para predadores não o incomoda.'),
(466, 'Electivire', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/466.png', 'Ele empurra as pontas de suas duas caudas contra o inimigo e depois libera mais de 20.000 volts de energia.'),
(467, 'Magmortar', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/467.png', 'Ele lança bolas de fogo a mais de 3.600 graus F das extremidades de seus braços. Vive em crateras vulcânicas.'),
(468, 'Togekiss', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/468.png', 'Nunca aparecerá onde houver conflito. Seus avistamentos tornaram-se raros recentemente.'),
(469, 'Yanmega', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/469.png', 'Ao bater as asas, ele cria ondas de choque que infligem ferimentos internos críticos aos inimigos.'),
(470, 'Leafeon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/470.png', 'Assim como uma planta, ela utiliza a fotossíntese. Como resultado, está sempre envolto em ar puro.'),
(471, 'Glaceon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/471.png', 'Como técnica de proteção, ele pode congelar completamente o pelo, fazendo com que os pelos fiquem como agulhas.'),
(472, 'Gliscor', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/472.png', 'Ele observa as presas penduradas invertidas nos galhos. Quando a oportunidade se apresenta, ela ataca!'),
(473, 'Mamoswine', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/473.png', 'Suas impressionantes presas são feitas de gelo. A população diminuiu quando esquentou após a era glacial.'),
(474, 'Porygon-z', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/474.png', 'Software adicional foi instalado para torná-lo um Pokémon melhor. Ele começou a agir de forma estranha, no entanto.'),
(475, 'Gallade', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/475.png', 'Mestre da cortesia e da esgrima, ele luta usando espadas estendidas nos cotovelos.'),
(476, 'Probopass', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/476.png', 'Ele exala forte magnetismo por toda parte. Ele controla três pequenas unidades chamadas Mini-Noses.'),
(477, 'Dusknoir', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/477.png', 'A antena em sua cabeça capta ondas de rádio do mundo dos espíritos que a comandam para levar as pessoas até lá.'),
(478, 'Froslass', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/478.png', 'Ele congela os inimigos com um hálito gelado a quase -60 graus F. O que parece ser seu corpo é na verdade oco.'),
(479, 'Rotom', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/479.png', 'Seu corpo é composto de plasma. É conhecido por se infiltrar em dispositivos eletrônicos e causar estragos.'),
(480, 'Uxie', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/480.png', 'Conhecido como “O Ser do Conhecimento”. Diz-se que pode apagar a memória de quem vê os seus olhos.'),
(481, 'Mesprit', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/481.png', 'Conhecido como “O Ser da Emoção”. Ensinou aos humanos a nobreza da tristeza, da dor e da alegria.'),
(482, 'Azelf', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/482.png', 'Conhecido como “O Ser da Força de Vontade”. Dorme no fundo de um lago para manter o equilíbrio do mundo.'),
(483, 'Dialga', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/483.png', 'Tem o poder de controlar o tempo. Aparece nos mitos da região de Sinnoh como uma antiga divindade.'),
(484, 'Palkia', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/484.png', 'Tem a capacidade de distorcer o espaço. É descrito como uma divindade na mitologia da região de Sinnoh.'),
(485, 'Heatran', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/485.png', 'Habita cavernas vulcânicas. Ele cava com seus pés em forma de cruz para rastejar em tetos e paredes.'),
(486, 'Regigigas', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/486.png', 'Existe uma lenda antiga que afirma que este Pokémon rebocou continentes com cordas.'),
(487, 'Giratina-altered', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/487.png', 'Dizem que um Pokémon vive em um mundo oposto ao nosso. Aparece em um antigo cemitério.'),
(488, 'Cresselia', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/488.png', 'Partículas brilhantes são liberadas de suas asas como um véu. Diz-se que representa a lua crescente.'),
(489, 'Phione', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/489.png', 'Um Pokémon que vive em mares quentes. Ele infla o saco de flutuação em sua cabeça para flutuar e procurar comida.'),
(490, 'Manaphy', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/490.png', 'Nascido no fundo do mar frio, ele nadará grandes distâncias para retornar ao seu local de nascimento.'),
(491, 'Darkrai', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/491.png', 'Pode acalmar as pessoas para dormir e fazê-las sonhar. Está ativo durante as noites de lua nova.'),
(492, 'Shaymin-land', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/492.png', 'Ele vive em canteiros de flores e evita ser detectado enrolando-se para se parecer com uma planta com flores.'),
(493, 'Arceus', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/493.png', 'É descrito na mitologia como o Pokémon que moldou o universo com seus 1.000 braços.'),
(494, 'Victini', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/494.png', 'Este Pokémon traz vitória. Diz-se que os Treinadores com Victini sempre vencem, independente do tipo de encontro.'),
(495, 'Snivy', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/495.png', 'É muito inteligente e calmo. Estar exposto a muita luz solar torna seus movimentos mais rápidos.'),
(496, 'Servine', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/496.png', 'Ele se move pelo chão como se estivesse deslizando. Seus movimentos rápidos confundem seus inimigos e então ele ataca com um chicote de videira.'),
(497, 'Serperior', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/497.png', 'Ele pode parar os movimentos dos seus oponentes com apenas um olhar. Ele absorve energia solar e a aumenta internamente.'),
(498, 'Tepig', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/498.png', 'Ele pode esquivar-se habilmente dos ataques do inimigo enquanto atira bolas de fogo pelo nariz. Ele assa frutas antes de comê-las.'),
(499, 'Pignite', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/499.png', 'Quando seu fogo interno se acende, seus movimentos ficam mais nítidos e rápidos. Quando está em apuros, emite fumaça.'),
(500, 'Emboar', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/500.png', 'Ele pode dar um soco de fogo colocando fogo em seus punhos com seu queixo de fogo. Ele se preocupa profundamente com seus amigos.'),
(501, 'Oshawott', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/501.png', 'Ele luta usando a concha na barriga. Em resposta a um ataque, ele retalia imediatamente cortando.'),
(502, 'Dewott', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/502.png', 'O treinamento rigoroso é como ele aprende sua técnica fluida de dupla concha.'),
(503, 'Samurott', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/503.png', 'Um golpe da espada incorporada em sua armadura pode derrubar um oponente. Um simples olhar de um deles acalma a todos.'),
(504, 'Patrat', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/504.png', 'Usando alimentos armazenados em bolsas nas bochechas, eles podem vigiar por dias. They use their tails to communicate with others.'),
(505, 'Watchog', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/505.png', 'Quando vêem um inimigo, suas caudas ficam erguidas e eles cospem as sementes das frutas armazenadas nas bolsas das bochechas.'),
(506, 'Lillipup', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/506.png', 'It faces strong opponents with great courage. Mas, quando está em desvantagem numa luta, este Pokémon inteligente foge.'),
(507, 'Herdier', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/507.png', 'Possui pêlo preto em forma de capa que é muito duro e diminui a quantidade de danos que recebe.'),
(508, 'Stoutland', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/508.png', 'Resgata pessoas presas por nevascas nas montanhas. Its shaggy fur shields it from the cold.'),
(509, 'Purrloin', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/509.png', 'Eles roubam as pessoas para se divertir, mas suas vítimas não conseguem evitar perdoá-los. Seu ato enganosamente fofo é perfeito.'),
(510, 'Liepard', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/510.png', 'Esses Pokémon desaparecem e aparecem inesperadamente. Muitos treinadores são atraídos por sua bela forma e pelo.'),
(511, 'Pansage', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/511.png', 'Este Pokémon vive nas profundezas da floresta. Comer uma folha da cabeça afasta o cansaço como num passe de mágica.'),
(512, 'Simisage', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/512.png', 'Mal humorado, ele luta balançando a cauda farpada descontroladamente. A folha que cresce em sua cabeça é muito amarga.'),
(513, 'Pansear', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/513.png', 'Quando está irritado, a temperatura do tufo da cabeça chega a 600° F. Ele usa o tufo para assar frutas.'),
(514, 'Simisear', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/514.png', 'Ele adora doces porque eles se transformam em energia para o fogo que arde dentro de seu corpo.'),
(515, 'Panpour', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/515.png', 'A água armazenada dentro do tufo de sua cabeça está cheia de nutrientes. As plantas que recebem sua água crescem grandes.'),
(516, 'Simipour', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/516.png', 'O tufo em sua cabeça retém água. Quando o nível está baixo, ele reabastece o tufo sugando água com sua cauda.'),
(517, 'Munna', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/517.png', 'Munna sempre flutua no ar. As pessoas cujos sonhos são devorados por elas esquecem sobre o que eram os sonhos.'),
(518, 'Musharna', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/518.png', 'A névoa que emana de suas testas está repleta de sonhos de pessoas e Pokémon.'),
(519, 'Pidove', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/519.png', 'Cada um segue as ordens do seu treinador da melhor maneira possível, mas às vezes não consegue entender comandos complicados.'),
(520, 'Tranquill', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/520.png', 'Ele pode retornar à localização do seu Treinador independentemente da distância que os separa.'),
(521, 'Unfezant', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/521.png', 'Os machos balançam a plumagem da cabeça para ameaçar os oponentes. As habilidades de voo das fêmeas superam as dos machos.'),
(522, 'Blitzle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/522.png', 'Sua juba brilha quando descarrega eletricidade. Eles usam suas crinas brilhantes para se comunicarem.'),
(523, 'Zebstrika', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/523.png', 'Eles têm movimentos semelhantes a raios. Quando Zebstrika corre a toda velocidade, o som do trovão reverbera.'),
(524, 'Roggenrola', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/524.png', 'Sua orelha tem formato hexagonal. Comprimido no subsolo, seu corpo é duro como aço.'),
(525, 'Boldore', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/525.png', 'Quando transborda de poder, o cristal laranja em seu corpo brilha. Procura água subterrânea em cavernas.'),
(526, 'Gigalith', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/526.png', 'Comprimir a energia de seu núcleo interno permite disparar um ataque capaz de explodir uma montanha.'),
(527, 'Woobat', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/527.png', 'Seu habitat são florestas escuras e cavernas. Ele emite ondas ultrassônicas pelo nariz para aprender sobre o que está ao seu redor.'),
(528, 'Swoobat', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/528.png', 'Ele emite ondas sonoras de várias frequências pelo seu nariz, incluindo algumas poderosas o suficiente para destruir rochas.'),
(529, 'Drilbur', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/529.png', 'Ele pode cavar o solo a uma velocidade de 30 mph. Isso poderia proporcionar a um carro rodando na superfície uma boa corrida.'),
(530, 'Excadrill', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/530.png', 'Pode ajudar na construção de túneis. Sua broca evoluiu para um aço forte o suficiente para perfurar placas de ferro.'),
(531, 'Audino', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/531.png', 'Ele toca os outros com as antenas nos ouvidos, usando o som dos batimentos cardíacos para dizer como estão se sentindo.'),
(532, 'Timburr', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/532.png', 'Ele luta balançando um pedaço de madeira. Está perto de evoluir quando consegue manusear a madeira sem dificuldade.'),
(533, 'Gurdurr', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/533.png', 'Este Pokémon é tão musculoso e forte que mesmo um grupo de lutadores não conseguiria fazê-lo se mover um centímetro.'),
(534, 'Conkeldurr', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/534.png', 'Pensa-se que Conkeldurr ensinou os humanos a fazer concreto há mais de 2.000 anos.'),
(535, 'Tympole', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/535.png', 'Eles alertam os outros sobre o perigo vibrando suas bochechas para criar um som agudo.'),
(536, 'Palpitoad', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/536.png', 'Quando vibram as saliências em suas cabeças, podem produzir ondas na água ou vibrações semelhantes às de um terremoto na terra.'),
(537, 'Seismitoad', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/537.png', 'Eles injetam um líquido paralisante com as pancadas na cabeça. Eles usam vibração para ferir seus oponentes.'),
(538, 'Throh', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/538.png', 'Quando aperta o cinto, fica mais forte. Wild Throh usa vinhas para tecer seus próprios cintos.'),
(539, 'Sawk', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/539.png', 'O som de Sawk socando pedras e árvores pode ser ouvido desde as montanhas onde eles treinam.'),
(540, 'Sewaddle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/540.png', 'Leaveanny veste-o com roupas que fizeram para ele quando nasceu. Ele esconde a cabeça no capuz enquanto dorme.'),
(541, 'Swadloon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/541.png', 'As florestas onde vivem Swadloon têm uma folhagem excelente porque os nutrientes que eles produzem das folhas caídas nutrem a vida das plantas.'),
(542, 'Leavanny', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/542.png', 'Ao encontrar um pequeno Pokémon, ele tece roupas para ele com folhas, usando os cortadores de seus braços e seda pegajosa.'),
(543, 'Venipede', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/543.png', 'Sua mordida injeta um veneno potente, suficiente para paralisar grandes pássaros Pokémon que tentam atacá-lo.'),
(544, 'Whirlipede', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/544.png', 'Protegido por uma casca dura, ele gira seu corpo como uma roda e se choca furiosamente contra seus inimigos.'),
(545, 'Scolipede', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/545.png', 'Com movimentos rápidos, ele persegue seus inimigos, atacando implacavelmente com seus chifres até prevalecer.'),
(546, 'Cottonee', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/546.png', 'Quando atacado, ele escapa atirando algodão de seu corpo. O algodão serve como isca para distrair o atacante.'),
(547, 'Whimsicott', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/547.png', 'Assim como o vento, ele pode passar por qualquer fenda, por menor que seja. Deixa bolas de penugem branca para trás.'),
(548, 'Petilil', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/548.png', 'As folhas da sua cabeça são muito amargas. Comer uma dessas folhas é conhecido por refrescar o corpo cansado.'),
(549, 'Lilligant', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/549.png', 'Até mesmo Treinadores veteranos enfrentam o desafio de fazer sua linda flor florescer. Este Pokémon é popular entre as celebridades.'),
(550, 'Basculin-red-striped', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/550.png', 'Basculin vermelho e azul se dão tão mal que começarão a lutar instantaneamente. Esses Pokémon são muito hostis.'),
(551, 'Sandile', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/551.png', 'Eles vivem enterrados nas areias do deserto. As areias aquecidas pelo sol evitam que a temperatura corporal caia.'),
(552, 'Krokorok', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/552.png', 'Eles vivem em grupos de poucos indivíduos. Membranas protetoras protegem seus olhos das tempestades de areia.'),
(553, 'Krookodile', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/553.png', 'Eles nunca permitem que a presa escape. Suas mandíbulas são tão poderosas que podem esmagar a carroceria de um automóvel.'),
(554, 'Darumaka', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/554.png', 'Quando seu fogo interno está queimando, ele não consegue se acalmar e corre. Quando o fogo diminui, ele adormece.'),
(555, 'Darmanitan-standard', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/555.png', 'Seu fogo interno queima a 2.500° F, produzindo energia suficiente para destruir um caminhão basculante com um soco.'),
(556, 'Maractus', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/556.png', 'Ele usa uma música e dança animada para afastar os pássaros Pokémon que atacam suas sementes de flores.'),
(557, 'Dwebble', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/557.png', 'Este Pokémon pode facilmente derreter buracos em rochas duras com um líquido secretado pela boca.'),
(558, 'Crustle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/558.png', 'Competindo por território, Crustle luta violentamente. Aquele cuja pedra está quebrada é o perdedor da batalha.'),
(559, 'Scraggy', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/559.png', 'Sua pele tem elasticidade emborrachada, por isso pode reduzir os danos puxando defensivamente a pele até o pescoço.'),
(560, 'Scrafty', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/560.png', 'Grupos deles espancam tudo que entra em seu território. Cada um pode cuspir líquido ácido da boca.'),
(561, 'Sigilyph', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/561.png', 'Eles nunca variam a rota que voam, porque suas memórias de guardar uma cidade antiga permanecem inabaláveis.'),
(562, 'Yamask', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/562.png', 'Cada um deles carrega uma máscara que era seu rosto quando era humano. Às vezes eles olham para isso e choram.'),
(563, 'Cofagrigus', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/563.png', 'Dizem que engolem quem se aproxima e os transformam em múmias. Eles gostam de comer pepitas de ouro.'),
(564, 'Tirtouga', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/564.png', 'Restaurado a partir de um fóssil, este Pokémon pode mergulhar a profundidades superiores a 800 metros.'),
(565, 'Carracosta', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/565.png', 'Eles podem viver tanto no oceano quanto em terra. Basta um tapa de um deles para abrir um buraco no fundo de um caminhão-tanque.'),
(566, 'Archen', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/566.png', 'Considerados ancestrais dos Pokémon pássaros, eles eram incapazes de voar e se moviam pulando de um galho para outro.'),
(567, 'Archeops', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/567.png', 'Eles são inteligentes e cooperarão para capturar suas presas. Do solo, eles começam a correr para voar.'),
(568, 'Trubbish', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/568.png', 'Inalar o gás que eles arrotam fará você dormir por uma semana. Eles preferem lugares insalubres.'),
(569, 'Garbodor', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/569.png', 'Ele aperta os oponentes com o braço esquerdo e acaba com eles com um gás venenoso e fedorento expelido de sua boca.'),
(570, 'Zorua', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/570.png', 'Ele muda para a forma dos outros para surpreendê-los. Aparentemente, muitas vezes se transforma em uma criança silenciosa.'),
(571, 'Zoroark', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/571.png', 'Os laços entre esses Pokémon são muito fortes. Ele protege a segurança de sua matilha enganando seus oponentes.'),
(572, 'Minccino', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/572.png', 'Eles se cumprimentam esfregando-se com o rabo, que está sempre bem cuidado e limpo.'),
(573, 'Cinccino', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/573.png', 'Seu pelo branco é revestido com um óleo especial que facilita a desviação de ataques.'),
(574, 'Gothita', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/574.png', 'Suas antenas em forma de fita aumentam seu poder psíquico. Eles estão sempre olhando para alguma coisa.'),
(575, 'Gothorita', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/575.png', 'Eles usam a hipnose para controlar pessoas e Pokémon. Histórias de Gothorita desencaminhando as pessoas são contadas em todos os cantos.'),
(576, 'Gothitelle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/576.png', 'Céus estrelados a milhares de anos-luz de distância são visíveis no espaço distorcidos pelo seu intenso poder psíquico.'),
(577, 'Solosis', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/577.png', 'Eles afastam os atacantes liberando poder psíquico. Eles podem usar a telepatia para conversar com outras pessoas.'),
(578, 'Duosion', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/578.png', 'Como têm dois cérebros divididos, às vezes tentam repentinamente realizar duas ações diferentes ao mesmo tempo.'),
(579, 'Reuniclus', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/579.png', 'Quando os Reuniclus apertam as mãos, uma rede se forma entre seus cérebros, aumentando seu poder psíquico.'),
(580, 'Ducklett', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/580.png', 'Esses Pokémon pássaros são excelentes mergulhadores. Eles nadam na água comendo sua comida favorita: turfa.'),
(581, 'Swanna', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/581.png', 'Swanna começa a dançar ao anoitecer. Aquele que dança no meio é o líder do rebanho.'),
(582, 'Vanillite', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/582.png', 'A temperatura de sua respiração é de -58° F. Eles criam cristais de neve e fazem a neve cair nas áreas ao seu redor.'),
(583, 'Vanillish', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/583.png', 'As montanhas nevadas são o habitat deste Pokémon. Durante uma antiga era glacial, eles se mudaram para as áreas do sul.'),
(584, 'Vanilluxe', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/584.png', 'Engolindo grandes quantidades de água, eles formam nuvens de neve dentro de seus corpos e atacam seus inimigos com violentas nevascas.'),
(585, 'Deerling', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/585.png', 'A cor e o cheiro de seu pelo mudam para combinar com a grama da montanha. Quando sentem hostilidade, escondem-se na grama.'),
(586, 'Sawsbuck', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/586.png', 'Eles migram de acordo com as estações. As pessoas podem saber a estação olhando para os chifres de Sawsbuck.'),
(587, 'Emolga', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/587.png', 'A energia produzida nas bolsas elétricas de suas bochechas é armazenada dentro de sua membrana e liberada enquanto ele desliza.'),
(588, 'Karrablast', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/588.png', 'Esses misteriosos Pokémon evoluem quando recebem estimulação elétrica enquanto estão no mesmo lugar que Shelmet.'),
(589, 'Escavalier', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/589.png', 'Eles voam em alta velocidade, atacando com suas lanças pontiagudas. Mesmo quando estão em apuros, eles enfrentam os adversários com bravura.'),
(590, 'Foongus', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/590.png', 'Ele atrai as pessoas com seu padrão Pokébola e depois libera esporos venenosos. Não se sabe por que se assemelha a uma Pokébola.'),
(591, 'Amoonguss', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/591.png', 'Ele atrai a presa para perto dançando e agitando os braços, que lembram Pokébolas, em um movimento oscilante.'),
(592, 'Frillish-male', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/592.png', 'Com seus braços finos em forma de véu enrolados no corpo do oponente, ele afunda no fundo do oceano.'),
(593, 'Jellicent-male', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/593.png', 'O destino dos navios e da tripulação que vagam pelo habitat de Jellicent: todos afundados, todos perdidos, todos desaparecidos.'),
(594, 'Alomomola', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/594.png', 'A membrana especial que envolve Alomomola tem a capacidade de curar feridas.'),
(595, 'Joltik', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/595.png', 'Os Joltik que vivem nas cidades aprenderam uma técnica para sugar eletricidade das tomadas das casas.'),
(596, 'Galvantula', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/596.png', 'Quando atacados, eles criam uma barreira elétrica cuspindo muitos fios eletricamente carregados.'),
(597, 'Ferroseed', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/597.png', 'Quando ameaçado, ele ataca disparando uma saraivada de espinhos, o que lhe dá a chance de escapar rolando.'),
(598, 'Ferrothorn', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/598.png', 'Ele luta girando em torno de suas três antenas pontiagudas. Um golpe dessas pontas de aço pode reduzir uma pedra a escombros.'),
(599, 'Klink', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/599.png', 'As duas miniengrenagens que se engrenam são predeterminadas. Cada um irá ricochetear em outros miniengrenagens sem engrenar.'),
(600, 'Klang', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/600.png', 'Ao mudar a direção em que gira, ele comunica seus sentimentos aos outros. Quando está com raiva, ele gira mais rápido.'),
(601, 'Klinklang', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/601.png', 'Seu núcleo vermelho funciona como um tanque de energia. Ele dispara a energia carregada através de seus espinhos em uma área.'),
(602, 'Tynamo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/602.png', 'Embora um sozinho não tenha muito poder, uma cadeia de muitos Tynamo pode ser tão poderosa quanto um raio.'),
(603, 'Eelektrik', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/603.png', 'Eles se enrolam em torno dos inimigos e os chocam com órgãos geradores de eletricidade que parecem simplesmente padrões circulares.'),
(604, 'Eelektross', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/604.png', 'Eles rastejam para fora do oceano usando os braços. Eles atacarão as presas na costa e imediatamente as arrastarão para o oceano.'),
(605, 'Elgyem', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/605.png', 'Ele usa seu forte poder psíquico para apertar o cérebro do oponente, causando dores de cabeça insuportáveis.'),
(606, 'Beheeyem', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/606.png', 'Pode manipular a memória de um oponente. Aparentemente, ele se comunica mostrando três dedos de cores diferentes.'),
(607, 'Litwick', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/607.png', 'Litwick emite uma luz que absorve a energia vital das pessoas e dos Pokémon, que se torna o combustível que queima.'),
(608, 'Lampent', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/608.png', 'Este Pokémon sinistro é temido. Ele vagueia pelas cidades, em busca dos espíritos dos caídos.'),
(609, 'Chandelure', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/609.png', 'Absorve um espírito, que depois queima. Ao agitar as chamas em seus braços, ele coloca seus inimigos em transe hipnótico.'),
(610, 'Axew', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/610.png', 'Eles usam suas presas para esmagar as frutas que comem. O crescimento repetido torna suas presas fortes e afiadas.'),
(611, 'Fraxure', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/611.png', 'Como uma presa quebrada não volta a crescer, eles afiam diligentemente suas presas nas rochas do rio depois de lutarem.'),
(612, 'Haxorus', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/612.png', 'Eles são gentis, mas podem ser implacáveis ​​na defesa do território. Eles desafiam os inimigos com presas que podem cortar aço.'),
(613, 'Cubchoo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/613.png', 'Quando não está se sentindo bem, seu muco fica aguado e o poder de seus movimentos do tipo Gelo diminui.'),
(614, 'Beartic', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/614.png', 'Ele pode congelar a respiração à vontade. Muito hábil na água, nada nos mares do norte e captura presas.'),
(615, 'Cryogonal', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/615.png', 'Quando a temperatura corporal aumenta, ele se transforma em vapor e desaparece. Quando sua temperatura diminui, ele retorna ao gelo.'),
(616, 'Shelmet', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/616.png', 'Quando atacado, defende-se fechando a tampa da sua concha. Pode cuspir um líquido pegajoso e venenoso.'),
(617, 'Accelgor', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/617.png', 'Quando seu corpo seca, ele enfraquece. Assim, para evitar a desidratação, envolve-se em muitas camadas de membrana fina.'),
(618, 'Stunfisk', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/618.png', 'Sua pele é muito dura, por isso não se machuca mesmo se for pisado por lutadores de sumô. Ele sorri ao transmitir eletricidade.'),
(619, 'Mienfoo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/619.png', 'Nas lutas, eles dominam com investidas de ataques fluidos e contínuos. Com suas garras afiadas, eles cortam os inimigos.'),
(620, 'Mienshao', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/620.png', 'Ele empunha o pelo dos braços como um chicote. Seus ataques de braço ocorrem com tanta rapidez que nem sequer podem ser vistos.'),
(621, 'Druddigon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/621.png', 'Aquece seu corpo absorvendo a luz solar com suas asas. Quando a temperatura corporal cai, ele não consegue mais se mover.'),
(622, 'Golett', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/622.png', 'A energia que queima dentro dele permite que ele se mova, mas ninguém ainda foi capaz de identificar essa energia.'),
(623, 'Golurk', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/623.png', 'Ele voa pelo céu em velocidades Mach. Remover o selo de seu peito faz com que sua energia interna fique fora de controle.'),
(624, 'Pawniard', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/624.png', 'As lâminas abrangem todo o corpo deste Pokémon. Se a batalha embota as lâminas, ela as afia nas pedras à beira do rio.'),
(625, 'Bisharp', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/625.png', 'Ele lidera um grupo de Pawniard. Ele luta para se tornar o chefe, mas será expulso do grupo se perder.'),
(626, 'Bouffalant', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/626.png', 'Seu pelo fofo absorve o dano, mesmo que atinjam os inimigos com uma cabeçada feroz.'),
(627, 'Rufflet', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/627.png', 'Eles esmagam frutas com suas garras. Eles enfrentam bravamente qualquer oponente, não importa quão forte ele seja.'),
(628, 'Braviary', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/628.png', 'Eles lutam por seus amigos sem pensar no perigo para si mesmos. Pode-se carregar um carro enquanto voa.'),
(629, 'Vullaby', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/629.png', 'Suas asas são muito pequenas para permitir que voe. À medida que se aproxima o tempo para evoluir, ele descarta os ossos que estava usando.'),
(630, 'Mandibuzz', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/630.png', 'Ele faz um ninho com os ossos que encontra. Ele agarra presas enfraquecidas com suas garras e as arrasta para seu ninho de ossos.'),
(631, 'Heatmor', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/631.png', 'Ele respira por um buraco na cauda enquanto queima com um fogo interno. Durant é sua presa.'),
(632, 'Durant', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/632.png', 'Eles atacam em grupos, cobrindo-se com armaduras de aço para se protegerem de Heatmor.'),
(633, 'Deino', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/633.png', 'Tende a morder tudo e não é um comedor exigente. Aproximar-se dele descuidadamente é perigoso.'),
(634, 'Zweilous', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/634.png', 'Depois de consumir toda a comida do seu território, ele se muda para outra área. Suas duas cabeças não se dão bem.'),
(635, 'Hydreigon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/635.png', 'Este Pokémon brutal viaja pelos céus com suas seis asas. Qualquer coisa que se mova parece um inimigo, desencadeando seu ataque.'),
(636, 'Larvesta', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/636.png', 'Acreditava-se que este Pokémon nasceu do sol. Quando evolui, todo o seu corpo é envolto em chamas.'),
(637, 'Volcarona', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/637.png', 'Quando as cinzas vulcânicas escureceram a atmosfera, diz-se que o fogo de Volcarona substituiu o sol.'),
(638, 'Cobalion', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/638.png', 'Este Pokémon lendário lutou contra humanos para proteger os Pokémon. Sua personalidade é calma e composta.'),
(639, 'Terrakion', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/639.png', 'Este Pokémon veio em defesa dos Pokémon que perderam suas casas em uma guerra entre humanos.'),
(640, 'Virizion', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/640.png', 'Este Pokémon lutou contra humanos para proteger seus amigos. Lendas sobre isso continuam a ser transmitidas.'),
(641, 'Tornadus-incarnate', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/641.png', 'A metade inferior do seu corpo está envolta em uma nuvem de energia. Ele voa pelo céu a 320 km/h.'),
(642, 'Thundurus-incarnate', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/642.png', 'Incontáveis ​​​​restos carbonizados prejudicam a paisagem dos lugares por onde Thundurus passou.'),
(643, 'Reshiram', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/643.png', 'Este Pokémon aparece em lendas. Ele envia chamas para o ar a partir de sua cauda, ​​queimando tudo ao seu redor.'),
(644, 'Zekrom', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/644.png', 'Escondendo-se em nuvens relâmpago, ele voa por toda a região de Unova. Ele cria eletricidade em sua cauda.'),
(645, 'Landorus-incarnate', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/645.png', 'As terras visitadas por Landorus concedem colheitas tão abundantes que ele foi aclamado como “O Guardião dos Campos”.'),
(646, 'Kyurem', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/646.png', 'Ele gera uma energia poderosa e congelante dentro de si, mas seu corpo ficou congelado quando a energia vazou.'),
(647, 'Keldeo-ordinary', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/647.png', 'Ao soprar água com seus cascos, ele pode deslizar pela água. É excelente no uso de movimentos de pernas durante a batalha.'),
(648, 'Meloetta-aria', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/648.png', 'Suas melodias são cantadas com um método especial de vocalização que consegue controlar os sentimentos de quem a ouve.'),
(649, 'Genesect', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/649.png', 'Há mais de 300 milhões de anos, era temido como o mais forte dos caçadores. Foi modificado pela Team Plasma.'),
(650, 'Chespin', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/650.png', 'As penas em sua cabeça são geralmente macias. Quando as flexiona, as pontas ficam tão duras e afiadas que podem perfurar rochas.'),
(651, 'Quilladin', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/651.png', 'Baseia-se na sua carapaça robusta para desviar os ataques dos predadores. Ele contra-ataca com seus espinhos afiados.'),
(652, 'Chesnaught', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/652.png', 'Seu equipamento é forte o suficiente para virar um tanque de 50 toneladas. Ele protege seus aliados do perigo com seu próprio corpo.'),
(653, 'Fennekin', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/653.png', 'Comer um galho o enche de energia, e suas orelhas espaçosas dão vazão ao ar mais quente que 390 graus Fahrenheit.'),
(654, 'Braixen', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/654.png', 'Tem um galho preso na cauda. Com a fricção do pelo da cauda, ​​ele incendeia o galho e se lança na batalha.'),
(655, 'Delphox', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/655.png', 'Ele olha para a chama na ponta do seu galho para atingir um estado focado, o que lhe permite ver o futuro.'),
(656, 'Froakie', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/656.png', 'Ele secreta bolhas flexíveis no peito e nas costas. As bolhas reduzem o dano que sofreria quando atacado.'),
(657, 'Frogadier', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/657.png', 'Ele pode lançar pedras cobertas de bolhas com controle preciso, atingindo latas vazias a até trinta metros de distância.'),
(658, 'Greninja', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/658.png', 'Ele cria estrelas a partir de água comprimida. Quando as gira e as lança em alta velocidade, essas estrelas podem partir o metal em dois.'),
(659, 'Bunnelby', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/659.png', 'Eles usam suas orelhas grandes para cavar tocas. Eles vão cavar a noite toda.'),
(660, 'Diggersby', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/660.png', 'Com seus ouvidos poderosos, eles podem levantar pedras de uma tonelada ou mais com facilidade. Eles podem ser uma grande ajuda nos canteiros de obras.'),
(661, 'Fletchling', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/661.png', 'Esses Pokémon amigáveis ​​enviam sinais uns aos outros com belos chilreios e movimentos das penas da cauda.'),
(662, 'Fletchinder', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/662.png', 'Do bico expele brasas que incendeiam a grama alta. Em seguida, ele ataca a presa desnorteada que surge da grama.'),
(663, 'Talonflame', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/663.png', 'Na febre de uma batalha emocionante, ele espalha brasas pelos espaços entre suas penas e alça voo.'),
(664, 'Scatterbug', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/664.png', 'Quando sob ataque de Pokémon pássaros, ele cospe um pó preto venenoso que causa paralisia ao contato.'),
(665, 'Spewpa', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/665.png', 'Ele vive escondido nas sombras do matagal. Quando os predadores atacam, ele rapidamente eriça o pelo que cobre seu corpo em um esforço para ameaçá-los.'),
(666, 'Vivillon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/666.png', 'Vivillon com diversos padrões são encontrados em todo o mundo. Esses padrões são afetados pelo clima de seu habitat.'),
(667, 'Litleo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/667.png', 'Quanto mais forte o adversário que enfrenta, mais calor surge da sua crina e mais energia flui através do seu corpo.'),
(668, 'Pyroar-male', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/668.png', 'O macho com a maior juba de fogo é o líder do bando.'),
(669, 'Flabebe', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/669.png', 'Ela extrai e controla o poder oculto das flores. A flor que Flabébé segura provavelmente faz parte de seu corpo.'),
(670, 'Floette', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/670.png', 'Ela esvoaça pelos campos floridos e cuida das flores que começam a murchar. Ela extrai o poder oculto das flores para a batalha.'),
(671, 'Florges', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/671.png', 'Ela reivindica belos jardins floridos como seu território e obtém força aproveitando a energia emitida pelas plantas com flores.'),
(672, 'Skiddo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/672.png', 'Considerado um dos primeiros Pokémon a viver em harmonia com os humanos, possui uma disposição plácida.'),
(673, 'Gogoat', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/673.png', 'Ele pode dizer como seu Treinador está se sentindo por meio de mudanças sutis no controle de seus chifres. Esse senso empático permite que eles corram como se fossem um só ser.'),
(674, 'Pancham', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/674.png', 'Faz o possível para ser levado a sério pelos seus inimigos, mas o seu olhar não é suficientemente intimidante. Mastigar uma folha é sua marca registrada.'),
(675, 'Pangoro', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/675.png', 'Embora possua um temperamento violento, não tolera bullying. Ele usa a folha na boca para sentir os movimentos de seus inimigos.'),
(676, 'Furfrou', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/676.png', 'Aparar seu pelo fofo não só o torna mais elegante, mas também aumenta a rapidez de seus movimentos.'),
(677, 'Espurr', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/677.png', 'O órgão que emite seu intenso poder psíquico é protegido pelos ouvidos para evitar que o poder vaze.'),
(678, 'Meowstic-male', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/678.png', 'Quando em perigo, ele levanta as orelhas e libera poder psíquico suficiente para transformar um caminhão de 10 toneladas em pó.'),
(679, 'Honedge', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/679.png', 'Aparentemente, este Pokémon nasce quando um espírito que partiu habita uma espada. Ele se liga às pessoas e bebe sua força vital.'),
(680, 'Doublade', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/680.png', 'Quando Honedge evolui, ele se divide em duas espadas, que cooperam via telepatia para coordenar ataques e cortar seus inimigos em pedaços.'),
(681, 'Aegislash-shield', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/681.png', 'Gerações de reis foram atendidas por esses Pokémon, que usaram seu poder espectral para manipular e controlar pessoas e Pokémon.'),
(682, 'Spritzee', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/682.png', 'Emite um perfume que encanta quem o cheira. Esta fragrância muda dependendo do que comeu.'),
(683, 'Aromatisse', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/683.png', 'Ele cria vários aromas, agradáveis ​​e desagradáveis, e emite aromas que seus inimigos não gostam para ganhar vantagem na batalha.'),
(684, 'Swirlix', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/684.png', 'Para enredar seus oponentes na batalha, ele expele fios brancos tão doces e pegajosos quanto algodão doce.'),
(685, 'Slurpuff', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/685.png', 'Ele pode distinguir o mais leve dos aromas. Ele usa seu olfato sensível ajudando os confeiteiros em seu trabalho.'),
(686, 'Inkay', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/686.png', 'Os oponentes que olham para o brilho dos pontos emissores de luz em seu corpo ficam atordoados e perdem a vontade de lutar.'),
(687, 'Malamar', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/687.png', 'Ele exerce os poderes hipnóticos mais atraentes de qualquer Pokémon e força os outros a fazerem o que quiserem.'),
(688, 'Binacle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/688.png', 'Dois Binacle vivem juntos em uma rocha. Quando eles lutam, um deles se moverá para uma rocha diferente.'),
(689, 'Barbaracle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/689.png', 'Quando evoluem, dois Bináculos se multiplicam em sete. Eles lutam com o poder dos sete bináculos.'),
(690, 'Skrelp', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/690.png', 'Camuflados como algas podres, eles borrifam veneno líquido nas presas que se aproximam de surpresa e depois acabam com elas.'),
(691, 'Dragalge', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/691.png', 'Seu veneno é forte o suficiente para corroer o casco de um navio-tanque, e eles o cospem indiscriminadamente em qualquer coisa que entre em seu território.'),
(692, 'Clauncher', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/692.png', 'Eles derrubam presas voadoras disparando água comprimida de suas enormes garras, como se disparassem uma pistola.'),
(693, 'Clawitzer', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/693.png', 'Suas enormes garras lançam balas de canhão de água poderosas o suficiente para perfurar cascos de petroleiros.'),
(694, 'Helioptile', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/694.png', 'Eles moram nos desertos. Eles podem gerar sua energia tomando sol, portanto, comer não é obrigatório.'),
(695, 'Heliolisk', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/695.png', 'Eles queimam seus babados e geram energia. Um único Heliolisk pode gerar eletricidade suficiente para alimentar um arranha-céu.'),
(696, 'Tyrunt', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/696.png', 'Este Pokémon foi restaurado a partir de um fóssil. Se acontecer algo que ele não gosta, ele faz birra e fica louco.'),
(697, 'Tyrantrum', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/697.png', 'Graças às suas mandíbulas gigantescas, que podiam destruir grossas placas de metal como se fossem papel, ele era invencível no mundo antigo que outrora habitou.'),
(698, 'Amaura', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/698.png', 'Este antigo Pokémon foi restaurado a partir de uma parte do seu corpo que estava congelada no gelo há mais de 100 milhões de anos.'),
(699, 'Aurorus', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/699.png', 'Os cristais em forma de diamante em seu corpo expelem ar tão frio quanto -240 graus Fahrenheit, cercando seus inimigos e envolvendo-os em gelo.'),
(700, 'Sylveon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/700.png', 'Ele envia uma aura calmante de suas antenas em forma de fita para acalmar as lutas.'),
(701, 'Hawlucha', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/701.png', 'Embora seu corpo seja pequeno, suas proficientes habilidades de luta permitem que ele acompanhe grandes lutadores como Machamp e Hariyama.'),
(702, 'Dedenne', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/702.png', 'Seus bigodes servem como antenas. Ao enviar e receber ondas elétricas, ele pode se comunicar com outras pessoas a grandes distâncias.'),
(703, 'Carbink', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/703.png', 'Nascido das temperaturas e pressões subterrâneas, ele dispara raios da pedra em sua cabeça.'),
(704, 'Goomy', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/704.png', 'O Pokémon do tipo Dragão mais fraco, vive em locais úmidos e sombreados, para que seu corpo não seque.'),
(705, 'Sliggoo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/705.png', 'Ele afasta os oponentes ao excretar um líquido pegajoso que pode dissolver qualquer coisa. Seus olhos evoluíram, então não consegue ver nada.'),
(706, 'Goodra', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/706.png', 'Este amigável Pokémon do tipo Dragão abraçará seu amado Treinador, deixando-o coberto de gosma pegajosa.'),
(707, 'Klefki', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/707.png', 'Esses coletores de chaves ameaçam qualquer invasor, agitando ferozmente suas chaves contra eles.'),
(708, 'Phantump', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/708.png', 'Esses Pokémon são criados quando os espíritos possuem tocos de árvores podres. Eles preferem viver em florestas abandonadas.'),
(709, 'Trevenant', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/709.png', 'Pode controlar árvores à vontade. Irá prender as pessoas que prejudicam a floresta, para que nunca possam sair.'),
(710, 'Pumpkaboo-average', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/710.png', 'O corpo da abóbora é habitado por um espírito preso neste mundo. À medida que o sol se põe, ele fica inquieto e ativo.'),
(711, 'Gourgeist-average', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/711.png', 'Cantando com vozes misteriosas, eles vagam pelas ruas da cidade na noite de lua nova. Qualquer um que ouve sua música é amaldiçoado.'),
(712, 'Bergmite', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/712.png', 'Bloqueia os ataques dos oponentes com o gelo que protege seu corpo. Ele usa ar frio para reparar quaisquer rachaduras com gelo novo.'),
(713, 'Avalugg', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/713.png', 'Seu corpo coberto de gelo é duro como aço. Sua estrutura pesada esmaga tudo que estiver em seu caminho.'),
(714, 'Noibat', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/714.png', 'Eles vivem em cavernas escuras. Suas enormes orelhas podem emitir ondas ultrassônicas de 200 mil hertz.'),
(715, 'Noivern', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/715.png', 'Eles voam em noites sem lua e atacam presas descuidadas. Nada pode vencê-los numa batalha no escuro.'),
(716, 'Xerneas', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/716.png', 'As lendas dizem que pode compartilhar a vida eterna. Dormiu durante mil anos na forma de uma árvore antes de renascer.'),
(717, 'Yveltal', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/717.png', 'Quando as asas e as penas da cauda deste Pokémon lendário se espalham e brilham em vermelho, ele absorve a força vital das criaturas vivas.'),
(718, 'Zygarde-50', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/718.png', 'Quando o ecossistema da região de Kalos entra em desordem, ele aparece e revela o seu poder secreto.'),
(719, 'Diancie', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/719.png', 'Uma transformação repentina de Carbink, seu corpo rosa e brilhante é considerado a visão mais linda do mundo.'),
(720, 'Hoopa', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/720.png', 'Este encrenqueiro envia tudo e qualquer coisa para lugares distantes usando seu loop, que pode distorcer o espaço.'),
(721, 'Volcanion', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/721.png', 'Solta ondas de vapor e desaparece na densa neblina. Diz-se que vive em montanhas onde os humanos não pisam.'),
(722, 'Rowlet', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/722.png', 'Este Pokémon cauteloso usa a fotossíntese para armazenar energia durante o dia, enquanto se torna ativo à noite.'),
(723, 'Dartrix', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/723.png', 'Um pouco elegante, passa o tempo livre alisando as asas. Sua preocupação com qualquer sujeira em sua plumagem pode torná-lo incapaz de lutar.'),
(724, 'Decidueye', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/724.png', 'Ele dispara flechas de suas asas com tanta precisão que elas podem perfurar uma pedra a distâncias superiores a cem metros.'),
(725, 'Litten', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/725.png', 'Enquanto se limpa, ele acumula pelos dentro do estômago. Ele incendeia o pelo e lança ataques de fogo, que mudam de acordo com a forma como ele tosse.'),
(726, 'Torracat', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/726.png', 'Na garganta carrega um sino de fogo. O sino toca intensamente sempre que este Pokémon cospe fogo.'),
(727, 'Incineroar', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/727.png', 'Este Pokémon tem uma disposição violenta e egoísta. Se não estiver com vontade de ouvir, ele irá ignorar as ordens do seu Treinador com total indiferença.'),
(728, 'Popplio', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/728.png', 'Este Pokémon cheira fluidos corporais pelo nariz, soprando balões para atingir seus inimigos. É famoso por ser um trabalhador esforçado.'),
(729, 'Brionne', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/729.png', 'Dançarino habilidoso, ele cria uma sequência de balões de água enquanto dança e bombardeia vigorosamente seus inimigos.'),
(730, 'Primarina', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/730.png', 'Ele controla seus balões de água com música. A melodia é aprendida com outros do gênero e transmitida de geração em geração.'),
(731, 'Pikipek', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/731.png', 'Ele pode bicar 16 vezes por segundo para fazer buracos em árvores. Utiliza os buracos para armazenamento de alimentos e para nidificação.'),
(732, 'Trumbeak', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/732.png', 'Come frutas e armazena suas sementes no bico. Quando encontra inimigos ou presas, ele dispara todas as sementes de uma só vez.'),
(733, 'Toucannon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/733.png', 'Quando luta, seu bico esquenta. A temperatura pode facilmente ultrapassar 212 graus Fahrenheit, causando queimaduras graves quando atinge.'),
(734, 'Yungoos', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/734.png', 'Com suas presas afiadas, ele morde qualquer coisa. Originalmente não vivia em Alola, mas foi importado de outra região.'),
(735, 'Gumshoos', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/735.png', 'Quando encontra vestígios de sua presa, ele pacientemente vigia o local... mas está sempre cochilando ao anoitecer.'),
(736, 'Grubbin', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/736.png', 'Sua mandíbula forte permite raspar árvores e sugar a seiva. Normalmente vive no subsolo.'),
(737, 'Charjabug', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/737.png', 'Seu corpo é capaz de armazenar eletricidade. Em acampamentos, as pessoas ficam gratas por ter um por perto.'),
(738, 'Vikavolt', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/738.png', 'Ele gira em torno, em busca de uma abertura. Ele concentra energia elétrica em suas grandes mandíbulas e a utiliza para destruir seus inimigos.'),
(739, 'Crabrawler', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/739.png', 'Enquanto guarda seus pontos fracos com suas pinças, procura uma abertura e desfere socos. Quando perde, espuma pela boca e desmaia.'),
(740, 'Crabominable', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/740.png', 'Almejou o topo, mas se perdeu e acabou em uma montanha nevada. Sendo forçado a suportar o frio, este Pokémon evoluiu e ganhou pêlo.'),
(741, 'Oricorio-baile', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/741.png', 'Ele bate as asas para criar fogo. À medida que se move nos passos de sua bela dança, banha os oponentes em chamas intensas.'),
(742, 'Cutiefly', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/742.png', 'Alimenta-se do néctar e do pólen das flores. Por ser capaz de sentir auras, pode identificar quais flores estão prestes a desabrochar.'),
(743, 'Ribombee', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/743.png', 'Ele enrola o pólen em baforadas. Produz muitas variedades diferentes, algumas usadas como alimento e outras em batalha.'),
(744, 'Rockruff', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/744.png', 'É considerado um bom Pokémon para iniciantes devido à sua simpatia, mas sua disposição fica mais difícil à medida que cresce.'),
(745, 'Lycanroc-midday', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/745.png', 'Seus movimentos rápidos confundem seus inimigos. Bem equipado com garras e presas, ele também usa as pedras afiadas de sua crina como armas.'),
(746, 'Wishiwashi-solo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/746.png', 'Quando está com problemas, seus olhos ficam umedecidos e começam a brilhar. A luz brilhante atrai seus camaradas, e eles se unem contra seus inimigos.'),
(747, 'Mareanie', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/747.png', 'Ele mergulha a ponta venenosa de sua cabeça em sua presa. Quando a presa enfraquece, Mareanie desfere o golpe final com seus 10 tentáculos.'),
(748, 'Toxapex', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/748.png', 'O Toxapex rasteja pelo fundo do oceano com suas 12 patas. Ele deixa um rastro de pedaços de Corsola espalhados em seu rastro.'),
(749, 'Mudbray', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/749.png', 'A lama grudada nos cascos do Mudbray melhora sua aderência e seu poderoso andar de corrida.'),
(750, 'Mudsdale', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/750.png', 'Cospe uma lama que oferece resistência ao vento e à chuva, por isso as paredes das casas antigas eram frequentemente revestidas com ela.'),
(751, 'Dewpider', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/751.png', 'Ele rasteja pela terra em busca de alimento. A sua bolha de água permite-lhe respirar e protege a sua cabeça macia.'),
(752, 'Araquanid', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/752.png', 'Ele dá cabeçadas com a bolha de água na cabeça. Pequenos Pokémon são sugados para dentro da bolha, onde se afogam.'),
(753, 'Fomantis', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/753.png', 'Durante o dia, dorme e absorve luz. Ao cair da noite, ele anda por aí em busca de um lugar mais seguro para dormir.'),
(754, 'Lurantis', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/754.png', 'É preciso muito esforço para manter as cores vivas do Lurantis, mas alguns colecionadores gostam desse trabalho e o tratam como seu hobby.'),
(755, 'Morelull', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/755.png', 'Ele espalha esporos que tremeluzem e brilham. Qualquer pessoa que veja essas luzes cai em um sono profundo.'),
(756, 'Shiinotic', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/756.png', 'As florestas onde vivem os Shiinotic são traiçoeiras para entrar à noite. Pessoas confusas com suas luzes estranhas nunca mais encontrarão o caminho de casa.'),
(757, 'Salandit', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/757.png', 'Ele queima seus fluidos corporais para criar um gás venenoso. Quando seus inimigos ficam desorientados ao inalar o gás, ele os ataca.'),
(758, 'Salazzle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/758.png', 'Por alguma razão, apenas mulheres foram encontradas. Ele cria um harém reverso de Salandit masculino com quem vive.'),
(759, 'Stufful', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/759.png', 'Apesar de sua aparência adorável, quando fica com raiva e se debate, seus braços e pernas podem derrubar um lutador profissional.'),
(760, 'Bewear', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/760.png', 'Este Pokémon imensamente perigoso possui uma força física avassaladora. Seu habitat geralmente está fora dos limites.'),
(761, 'Bounsweet', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/761.png', 'Um aroma delicioso emana de seu corpo. Muitas vezes são engolidos inteiros por Tucanos atraídos por aquela delícia flutuante.'),
(762, 'Steenee', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/762.png', 'As sépalas em sua cabeça foram desenvolvidas para proteger seu corpo. Estes são bastante difíceis, por isso, mesmo que seja bicado por Pokémon pássaros, este Pokémon está perfeitamente bem.'),
(763, 'Tsareena', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/763.png', 'Suas pernas longas e impressionantes não são apenas para exibição, mas para serem usadas para chutar com habilidade. Na vitória, se exibe chutando os derrotados, rindo ruidosamente.'),
(764, 'Comfey', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/764.png', 'Ele atribui flores à sua videira altamente nutritiva. Isso revitaliza as flores e elas exalam um perfume aromático.'),
(765, 'Oranguru', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/765.png', 'Conhecido por sua extrema inteligência, este Pokémon desprezará treinadores inexperientes, por isso é mais adequado para treinadores veteranos.'),
(766, 'Passimian', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/766.png', 'Eles formam grupos de aproximadamente 20 indivíduos. O vínculo mútuo deles é notável – eles nunca decepcionarão um camarada.'),
(767, 'Wimpod', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/767.png', 'Este Pokémon é um covarde. Enquanto ele sai correndo desesperadamente, o movimento de suas muitas pernas deixa um rastro limpo e brilhante em seu rastro.'),
(768, 'Golisopod', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/768.png', 'Com um golpe brilhante de suas gigantescas garras afiadas, ele corta a água do mar — ou mesmo o ar — em dois.'),
(769, 'Sandygast', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/769.png', 'Nascido de um monte de areia construído de forma divertida por uma criança, este Pokémon personifica os rancores dos que partiram.'),
(770, 'Palossand', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/770.png', 'Pessoas possuídas e controladas por este Pokémon transformaram seu monte de areia em um castelo. À medida que evoluiu, seu poder de amaldiçoar ficou cada vez mais forte.'),
(771, 'Pyukumuku', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/771.png', 'Vive em mares rasos, como áreas próximas à praia. Ele pode ejetar seus órgãos internos, que usa para engolir suas presas ou lutar contra inimigos.'),
(772, 'Type-null', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/772.png', 'A pesada máscara de controle que ele usa suprime suas capacidades intrínsecas. Este Pokémon tem algum poder especial oculto.'),
(773, 'Silvally', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/773.png', 'A confiança no parceiro é o que a desperta. Este Pokémon é capaz de mudar de tipo, uma flexibilidade que fica bem demonstrada em batalha.'),
(774, 'Minior-red-meteor', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/774.png', 'Originalmente morando na camada de ozônio, ele cai no chão quando a concha que envolve seu corpo fica muito pesada.'),
(775, 'Komala', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/775.png', 'Nasce dormindo e morre dormindo. Todos os seus movimentos aparentemente nada mais são do que o resultado de seus movimentos e reviravoltas em seus sonhos.'),
(776, 'Turtonator', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/776.png', 'A concha em suas costas é quimicamente instável e explode violentamente se for atingida. O buraco no estômago é o seu ponto fraco.'),
(777, 'Togedemaru', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/777.png', 'O pelo espinhoso do dorso normalmente está em repouso. Quando este Pokémon fica agitado, seu pelo se arrepia e ataca seus atacantes.'),
(778, 'Mimikyu-disguised', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/778.png', 'Sua aparência real é desconhecida. Um estudioso que viu o que estava sob seu trapo foi dominado pelo terror e morreu em choque.'),
(779, 'Bruxish', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/779.png', 'Quando ele libera seu poder psíquico da protuberância em sua cabeça, o som áspero de ranger de dentes ecoa pela área.'),
(780, 'Drampa', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/780.png', 'Tem uma personalidade compassiva, mas se ficar irritado, destrói completamente o que o rodeia com a sua respiração intensa.'),
(781, 'Dhelmise', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/781.png', 'Balançando sua enorme âncora, ele pode nocautear Wailord com um único golpe. O que parece ser uma alga verde é na verdade o seu corpo.'),
(782, 'Jangmo-o', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/782.png', 'Ele expressa seus sentimentos batendo em suas escamas. Sons metálicos ecoam pelas altas montanhas onde Jangmo-o mora.'),
(783, 'Hakamo-o', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/783.png', 'Ele salta sobre sua presa com um grito corajoso. Seus socos escamosos destroem seus oponentes.'),
(784, 'Kommo-o', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/784.png', 'Quando avista inimigos, ele os ameaça balançando as escamas da cauda. Oponentes fracos irão quebrar e fugir em pânico.'),
(785, 'Tapu-koko', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/785.png', 'Esta divindade guardiã de Melemele está repleta de curiosidade. Ele invoca nuvens de tempestade e armazena seus raios dentro de seu corpo.'),
(786, 'Tapu-lele', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/786.png', 'Esta divindade guardiã de Akala é inocentemente cruel. O aroma perfumado das flores é a fonte de sua energia.'),
(787, 'Tapu-bulu', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/787.png', 'Ele puxa grandes árvores pelas raízes e as balança. Faz com que a vegetação cresça e então absorve a energia do crescimento.'),
(788, 'Tapu-fini', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/788.png', 'A densa neblina que ele cria traz a queda e destruição de seus confusos inimigos. As correntes oceânicas são a fonte de sua energia.'),
(789, 'Cosmog', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/789.png', 'Seu corpo é gasoso e frágil. Ele cresce lentamente à medida que coleta poeira da atmosfera.'),
(790, 'Cosmoem', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/790.png', 'Imóvel como se estivesse morto, seu corpo está levemente quente ao toque. No passado distante, era chamado de casulo das estrelas.'),
(791, 'Solgaleo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/791.png', 'Diz-se que vive em outro mundo. A luz intensa que irradia da superfície de seu corpo pode fazer com que as noites mais escuras se iluminem como o meio-dia.'),
(792, 'Lunala', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/792.png', 'Diz-se que é uma evolução feminina do Cosmog. Quando seu terceiro olho é ativado, ele voa para outro mundo.'),
(793, 'Nihilego', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/793.png', 'Uma das várias Ultra Beasts misteriosas. Pessoas nas ruas relatam observar aqueles infestados por ela de repente se tornarem violentos.'),
(794, 'Buzzwole', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/794.png', 'Esta Ultra Besta apareceu de outro mundo. Ele exibe seu corpo, mas ainda não está claro se essa exibição é uma ostentação ou uma ameaça.'),
(795, 'Pheromosa', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/795.png', 'Uma das perigosas Ultra Beasts, foi vista correndo pela terra em velocidades incríveis.'),
(796, 'Xurkitree', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/796.png', 'Uma das misteriosas formas de vida conhecidas como Ultra Beasts. Choques elétricos surpreendentes emanam de todo o seu corpo, segundo testemunhas.'),
(797, 'Celesteela', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/797.png', 'Apareceu do Ultra Wormhole. Testemunhas observaram-no voando pelo céu em alta velocidade.'),
(798, 'Kartana', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/798.png', 'Esta Ultra Besta veio do Ultra Wormhole. Parece não atacar os inimigos por si só, mas seu corpo afiado é uma arma perigosa por si só.'),
(799, 'Guzzlord', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/799.png', 'Devorou ​​montanhas e engoliu edifícios inteiros, segundo relatos. É uma das Ultra Bestas.'),
(800, 'Necrozma', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/800.png', 'Uma reminiscência das Ultra Beasts, acredita-se que esta forma de vida, aparentemente adormecida no subsolo, tenha vindo de outro mundo nos tempos antigos.'),
(801, 'Magearna', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/801.png', 'Este Pokémon artificial, construído há mais de 500 anos, pode compreender a fala humana, mas não consegue falar.'),
(802, 'Marshadow', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/802.png', 'Capaz de se esconder nas sombras, ele nunca aparece diante dos humanos, então sua própria existência era matéria de mito.'),
(803, 'Poipole', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/803.png', 'Esta Ultra Besta é bastante apreciada para ser escolhida como primeira parceira em seu próprio mundo.'),
(804, 'Naganadel', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/804.png', 'Armazena centenas de litros de líquido venenoso dentro de seu corpo. É um dos organismos conhecidos como UBs.'),
(805, 'Stakataka', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/805.png', 'Apareceu de um Ultra Wormhole. Cada um parece ser composto de muitas formas de vida empilhadas umas sobre as outras.'),
(806, 'Blacephalon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/806.png', 'Ele desliza em direção às pessoas. Então, sem aviso, provoca a explosão de sua própria cabeça. Aparentemente é um tipo de Ultra Beast.'),
(807, 'Zeraora', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/807.png', 'Ele eletrifica suas garras e destrói seus oponentes com elas. Mesmo que eles evitem o ataque, serão eletrocutados pelas faíscas voadoras.'),
(808, 'Meltan', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/808.png', 'Ele derrete partículas de ferro e outros metais encontrados no subsolo, para que possa absorvê-los em seu corpo de aço fundido.'),
(809, 'Melmetal', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/809.png', 'Reverenciado há muito tempo pela sua capacidade de criar ferro a partir do nada, por alguma razão voltou à vida após 3.000 anos.'),
(810, 'Grookey', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/810.png', 'Quando ele usa seu bastão especial para bater, as ondas sonoras produzidas transportam energia revitalizante para as plantas e flores da região.'),
(811, 'Thwackey', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/811.png', 'Quanto mais rápido um Thwackey consegue bater um ritmo com suas duas baquetas, mais respeito ele ganha de seus colegas.'),
(812, 'Rillaboom', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/812.png', 'Ao tocar tambor, ele aproveita o poder de seu toco de árvore especial. As raízes do toco seguem sua direção na batalha.'),
(813, 'Scorbunny', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/813.png', 'Um aquecimento de corrida faz com que a energia do fogo percorra o corpo deste Pokémon. Quando isso acontecer, ele estará pronto para lutar com força total.'),
(814, 'Raboot', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/814.png', 'Seu pelo grosso e fofo protege-o do frio e permite-lhe usar movimentos de fogo mais quentes.'),
(815, 'Cinderace', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/815.png', 'Ele faz malabarismos com uma pedra com os pés, transformando-a em uma bola de futebol em chamas. Seus tiros atingem com força os oponentes e os deixam queimados.'),
(816, 'Sobble', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/816.png', 'Quando assustado, este Pokémon chora. Suas lágrimas contêm o poder químico de 100 cebolas, e os atacantes não conseguirão resistir ao choro.'),
(817, 'Drizzile', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/817.png', 'Um combatente inteligente, este Pokémon luta usando balões de água criados com a umidade secretada pelas palmas das mãos.'),
(818, 'Inteleon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/818.png', 'Ele possui muitos recursos ocultos, como pontas dos dedos que podem atirar água e uma membrana nas costas que pode usar para deslizar no ar.'),
(819, 'Skwovet', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/819.png', 'Encontrado em toda a região de Galar, este Pokémon fica inquieto se suas bochechas ficarem completamente vazias de frutas.'),
(820, 'Greedent', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/820.png', 'Ele esconde frutas na cauda - tantas frutas que caem constantemente. Mas este Pokémon é um pouco lento, por isso não percebe a perda.'),
(821, 'Rookidee', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/821.png', 'Ele desafiará corajosamente qualquer oponente, não importa quão poderoso seja. Este Pokémon se beneficia de todas as batalhas – até mesmo uma derrota aumenta um pouco sua força.'),
(822, 'Corvisquire', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/822.png', 'Inteligentes o suficiente para usar ferramentas em batalha, esses Pokémon foram vistos pegando pedras e atirando-as ou usando cordas para envolver os inimigos.'),
(823, 'Corviknight', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/823.png', 'Este Pokémon reina supremo nos céus da região de Galar. O brilho negro do seu corpo de aço poderia levar o terror ao coração de qualquer inimigo.'),
(824, 'Blipbug', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/824.png', 'Constante coletor de informações, este Pokémon é muito inteligente. Muito forte é o que não é.'),
(825, 'Dottler', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/825.png', 'Ele mal se move, mas ainda está vivo. Esconder-se em sua concha sem comida ou água parece ter despertado seus poderes psíquicos.'),
(826, 'Orbeetle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/826.png', 'É famoso pelo seu alto nível de inteligência, e o grande tamanho do seu cérebro é prova de que também possui imenso poder psíquico.'),
(827, 'Nickit', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/827.png', 'Auxiliado pelas almofadas macias dos pés, ele ataca silenciosamente os estoques de alimentos de outros Pokémon. Ele sobrevive de seus ganhos ilícitos.'),
(828, 'Thievul', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/828.png', 'Marca secretamente alvos potenciais com um perfume. Ao seguir o cheiro, ele persegue seus alvos e os rouba quando menos esperam.'),
(829, 'Gossifleur', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/829.png', 'Ele se ancora no solo com uma única perna e depois se aquece ao sol. Depois de absorver luz solar suficiente, suas pétalas se espalham enquanto ela floresce brilhantemente.'),
(830, 'Eldegoss', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/830.png', 'As sementes presas à penugem do algodão estão cheias de nutrientes. Ele os espalha ao vento para que as plantas e outros Pokémon possam se beneficiar deles.'),
(831, 'Wooloo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/831.png', 'O seu velo encaracolado é uma almofada tão eficaz que este Pokémon pode cair de um penhasco e ficar no fundo, ileso.'),
(832, 'Dubwool', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/832.png', 'Faça um tapete com sua lã elástica e você terá algo mais parecido com um trampolim. Você começará a pular no momento em que pisar nele.'),
(833, 'Chewtle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/833.png', 'Aparentemente, a coceira causada pela dentição o impele a morder qualquer coisa à sua frente.'),
(834, 'Drednaw', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/834.png', 'Com mandíbulas que podem cortar barras de aço, este Pokémon altamente agressivo mastiga sua infeliz presa.'),
(835, 'Yamper', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/835.png', 'Este Pokémon é muito popular como cão pastor na região de Galar. À medida que corre, gera eletricidade a partir da base da cauda.'),
(836, 'Boltund', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/836.png', 'Este Pokémon gera eletricidade e a canaliza para suas pernas para mantê-las fortes. Boltund pode funcionar sem parar por três dias inteiros.'),
(837, 'Rolycoly', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/837.png', 'A maior parte do seu corpo tem a mesma composição do carvão. Apropriadamente, este Pokémon foi descoberto pela primeira vez em minas de carvão há cerca de 400 anos.'),
(838, 'Carkol', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/838.png', 'Forma carvão dentro de seu corpo. O carvão deixado por este Pokémon já ajudou a abastecer a vida das pessoas na região de Galar.'),
(839, 'Coalossal', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/839.png', 'Geralmente é pacífico, mas o vandalismo das minas o enfurece. Os infratores serão incinerados com chamas que chegam a 2.700 graus Fahrenheit.'),
(840, 'Applin', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/840.png', 'Passa a vida inteira dentro de uma maçã. Ele se esconde de seus inimigos naturais, os Pokémon pássaros, fingindo que é apenas uma maçã e nada mais.'),
(841, 'Flapple', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/841.png', 'Comeu uma maçã azeda e isso induziu a sua evolução. Em suas bochechas armazena um ácido capaz de causar queimaduras químicas.'),
(842, 'Appletun', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/842.png', 'Comer uma maçã doce causou sua evolução. Um cheiro de néctar exala de seu corpo, atraindo o Pokémon inseto que ele ataca.'),
(843, 'Silicobra', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/843.png', 'Ao cavar, ele engole areia e a armazena na bolsa do pescoço. A bolsa pode conter mais de 17 quilos de areia.'),
(844, 'Sandaconda', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/844.png', 'Quando ele contrai o corpo, mais de 220 quilos de areia saem de seu nariz. Se alguma vez ficar sem areia, fica desanimado.'),
(845, 'Cramorant', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/845.png', 'É tão forte que pode nocautear alguns oponentes com um único golpe, mas também pode esquecer o que está enfrentando no meio da luta.'),
(846, 'Arrokuda', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/846.png', 'Se vir algum movimento ao seu redor, este Pokémon ataca imediatamente, liderando com sua mandíbula pontiaguda. Está muito orgulhoso dessa mandíbula.'),
(847, 'Barraskewda', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/847.png', 'Este Pokémon tem uma mandíbula afiada como uma lança e forte como aço. Aparentemente, a carne de Barraskewda também é surpreendentemente saborosa.'),
(848, 'Toxel', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/848.png', 'Ele armazena veneno em um saco interno de veneno e o secreta através de sua pele. Se você tocar neste Pokémon, você sentirá uma sensação de formigamento.'),
(849, 'Toxtricity-amped', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/849.png', 'Quando este Pokémon soa como se estivesse dedilhando uma guitarra, na verdade ele está arranhando as saliências do peito para gerar eletricidade.'),
(850, 'Sizzlipede', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/850.png', 'Ele armazena gás inflamável em seu corpo e o utiliza para gerar calor. As seções amarelas da barriga ficam particularmente quentes.'),
(851, 'Centiskorch', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/851.png', 'Quando aquece, a temperatura corporal atinge cerca de 1.500 graus Fahrenheit. Ele açoita seu corpo como um chicote e se lança contra os inimigos.'),
(852, 'Clobbopus', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/852.png', 'É muito curioso, mas seu meio de investigar as coisas é tentar acertá-las com seus tentáculos. A busca por alimento é o que o traz para terra.'),
(853, 'Grapploct', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/853.png', 'Um corpo feito apenas de músculos torna os movimentos de luta que este Pokémon realiza com seus tentáculos tremendamente poderosos.'),
(854, 'Sinistea', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/854.png', 'Diz-se que este Pokémon nasceu quando um espírito solitário possuía uma xícara de chá fria que sobrou.'),
(855, 'Polteageist', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/855.png', 'Esta espécie vive em bules antigos. A maioria dos potes são falsificações, mas em raras ocasiões é encontrada uma obra autêntica.'),
(856, 'Hatenna', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/856.png', 'Através da saliência na sua cabeça, ele sente as emoções de outras criaturas. Se você não tiver uma disposição calma, isso nunca será afetuoso com você.'),
(857, 'Hattrem', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/857.png', 'Não importa quem você seja, se você trouxer emoções fortes para perto deste Pokémon, ele irá silenciá-lo violentamente.'),
(858, 'Hatterene', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/858.png', 'Ele emite poder psíquico forte o suficiente para causar dores de cabeça como um impedimento à abordagem de outras pessoas.'),
(859, 'Impidimp', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/859.png', 'Pelo nariz, suga as emanações produzidas pelas pessoas e Pokémon quando se sentem irritados. Ele prospera com essa energia negativa.'),
(860, 'Morgrem', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/860.png', 'Quando ele fica de quatro, como se implorasse por perdão, ele tenta atrair os oponentes para que possa apunhalá-los com seu cabelo semelhante a uma lança.'),
(861, 'Grimmsnarl', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/861.png', 'Com o cabelo enrolado no corpo ajudando a fortalecer os músculos, este Pokémon pode sobrecarregar até mesmo Machamp.'),
(862, 'Obstagoon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/862.png', 'Sua voz é impressionante em volume. Obstagoon tem tendência a assumir uma postura ameaçadora e gritar – esse movimento é conhecido como Obstruir.'),
(863, 'Perrserker', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/863.png', 'O que parece ser um capacete de ferro é na verdade cabelo endurecido. Este Pokémon vive para a emoção da batalha.'),
(864, 'Cursola', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/864.png', 'Sua concha está transbordando com sua elevada energia sobrenatural. O ectoplasma serve como proteção para o espírito central deste Pokémon.'),
(865, 'Sirfetchd', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/865.png', 'Somente Farfetch’d que sobreviveu a muitas batalhas pode atingir esta evolução. Quando o alho-poró deste Pokémon murchar, ele se retirará do combate.'),
(866, 'Mr-rime', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/866.png', 'É altamente hábil em sapateado. Ele balança sua bengala de gelo no ritmo de seus movimentos graciosos.'),
(867, 'Runerigus', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/867.png', 'Uma maldição poderosa foi tecida em uma pintura antiga. Após absorver o espírito de um Yamask, a pintura começou a se mover.'),
(868, 'Milcery', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/868.png', 'Este Pokémon nasceu de partículas de cheiro doce no ar. Seu corpo é feito de creme.'),
(869, 'Alcremie', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/869.png', 'Quando confia em um Treinador, ele o trata com frutas decoradas com creme.'),
(870, 'Falinks', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/870.png', 'Cinco deles são soldados e um é o chefe. As ordens dos chefes são absolutas.'),
(871, 'Pincurchin', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/871.png', 'Alimenta-se de algas marinhas, usando os dentes para arrancá-las das rochas. A corrente elétrica flui das pontas de suas espinhas.'),
(872, 'Snom', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/872.png', 'Ele cospe um fio imbuído de uma espécie de energia frígida e o usa para amarrar seu corpo aos galhos, disfarçando-se de pingente de gelo enquanto dorme.'),
(873, 'Frosmoth', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/873.png', 'Escamas geladas caem de suas asas como neve enquanto ele voa sobre campos e montanhas. A temperatura de suas asas é inferior a -290 graus Fahrenheit.'),
(874, 'Stonjourner', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/874.png', 'Fica nas pastagens, observando a descida do sol do zênite ao horizonte. Este Pokémon tem talento para desferir chutes dinâmicos.'),
(875, 'Eiscue-ice', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/875.png', 'Ele flutuou no fluxo das águas do oceano de um lugar gelado. Ele mantém a cabeça gelada constantemente para garantir que permaneça bem e fria.'),
(876, 'Indeedee-male', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/876.png', 'Ele usa os chifres na cabeça para sentir as emoções dos outros. Os homens atuarão como manobristas para aqueles a quem servem, cuidando de todas as suas necessidades.'),
(877, 'Morpeko-full-belly', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/877.png', 'Ao comer as sementes armazenadas em suas bolsas, este Pokémon não está apenas satisfazendo sua fome constante. Também está gerando eletricidade.'),
(878, 'Cufant', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/878.png', 'Ele escava o chão com seu tronco. Também é muito resistente, podendo transportar cargas de mais de cinco toneladas sem nenhum problema.'),
(879, 'Copperajah', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/879.png', 'Eles vieram de outra região há muito tempo e trabalharam juntos com humanos. Sua pele verde é resistente à água.'),
(880, 'Dracozolt', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/880.png', 'Nos tempos antigos, era imbatível graças à sua poderosa parte inferior do corpo, mas foi extinto de qualquer maneira depois de esgotar todas as suas fontes alimentares vegetais.'),
(881, 'Arctozolt', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/881.png', 'A agitação de sua metade superior congelada é o que gera sua eletricidade. É difícil andar por aí.'),
(882, 'Dracovish', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/882.png', 'Pernas e mandíbulas poderosas fizeram dele o predador máximo de seu tempo. A própria caça excessiva de suas presas foi o que o levou à extinção.'),
(883, 'Arctovish', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/883.png', 'Embora seja capaz de capturar a presa congelando o ambiente, ele tem dificuldade em comê-la depois porque sua boca fica no topo da cabeça.'),
(884, 'Duraludon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/884.png', 'Seu corpo lembra metal polido e é leve e forte. A única desvantagem é que enferruja facilmente.'),
(885, 'Dreepy', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/885.png', 'Depois de renascer como um Pokémon fantasma, Dreepy vagueia pelas áreas que habitava quando estava vivo nos mares pré-históricos.'),
(886, 'Drakloak', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/886.png', 'É capaz de voar a mais de 190 km/h. Ele luta ao lado de Dreepy e os adora até que evoluam com sucesso.'),
(887, 'Dragapult', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/887.png', 'Quando não está lutando, mantém Dreepy nos buracos de seus chifres. Assim que a luta começa, ele lança os Dreepy como mísseis supersônicos.'),
(888, 'Zacian', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/888.png', 'Conhecido como um herói lendário, este Pokémon absorve partículas de metal, transformando-as em uma arma que utiliza para a batalha.'),
(889, 'Zamazenta', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/889.png', 'Em tempos passados, trabalhou em conjunto com um rei do povo para salvar a região de Galar. Ele absorve metal que usa em batalha.'),
(890, 'Eternatus', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/890.png', 'O núcleo em seu peito absorve a energia que emana das terras da região de Galar. Essa energia é o que permite que Eternatus permaneça ativo.'),
(891, 'Kubfu', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/891.png', 'Kubfu treina muito para aperfeiçoar seus movimentos. Os movimentos que ele dominar determinarão a forma que ele assumirá quando evoluir.'),
(892, 'Urshifu-single-strike', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/892.png', 'Esta forma de Urshifu acredita fortemente no nocaute de um golpe. Sua estratégia é saltar perto dos inimigos e desferir um golpe devastador com o punho endurecido.'),
(893, 'Zarude', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/893.png', 'Dentro de florestas densas, este Pokémon vive em matilha com outros de sua espécie. É incrivelmente agressivo e os outros Pokémon da floresta o temem.'),
(894, 'Regieleki', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/894.png', 'Este Pokémon é um aglomerado de energia elétrica. Diz-se que remover os anéis do corpo de Regieleki irá liberar o poder latente do Pokémon.'),
(895, 'Regidrago', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/895.png', 'Uma teoria acadêmica propõe que os braços de Regidrago já foram a cabeça de um antigo Pokémon dragão. A teoria permanece sem comprovação.'),
(896, 'Glastrier', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/896.png', 'Glastrier emite frio intenso com seus cascos. É também um Pokémon beligerante – tudo o que quer, é preciso à força.'),
(897, 'Spectrier', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/897.png', 'Ele sonda o ambiente ao seu redor com todos os seus sentidos, exceto um – ele não usa o sentido da visão. Dizem que os chutes de Spectrier separam a alma do corpo.'),
(898, 'Calyrex', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/898.png', 'Calyrex é um Pokémon misericordioso, capaz de proporcionar cura e bênçãos. Reinou sobre a região de Galar em tempos passados.'),
(899, 'Wyrdeer', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/899.png', 'Os orbes negros brilham com uma luz misteriosa quando o Pokémon ergue barreiras invisíveis. A pele que sai da barba retém bem o calor e é um material muito útil para roupas de inverno.'),
(900, 'Kleavor', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/900.png', 'Uma criatura violenta que derruba árvores imponentes com seus machados rudimentares e se protege com pedras duras. Se alguém encontrar este Pokémon na selva, o único recurso é fugir.'),
(901, 'Ursaluna', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/901.png', 'Acredito que foi o terreno pantanoso de Hisui que deu a Ursaluna seu físico corpulento e sua nova capacidade de manipular turfa à vontade.'),
(902, 'Basculegion-male', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/902.png', 'Reveste-se nas almas dos camaradas que morreram antes de cumprirem seus objetivos de jornada rio acima. Nenhuma outra espécie em todos os rios de Hisui é igual a Basculegion.'),
(903, 'Sneasler', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/903.png', 'Por causa do veneno virulento de Sneasler e de suas proezas físicas assustadoras, nenhuma outra espécie poderia esperar superá-lo nas terras altas congeladas. Preferindo a solidão, esta espécie não forma matilhas.'),
(904, 'Overqwil', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/904.png', 'Suas pontas em forma de lança e seu temperamento selvagem lhe valeram o apelido de “demônio do mar”. Ele suga veneno para se alimentar.'),
(905, 'Enamorus-incarnate', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/905.png', 'Quando ele voa para esta terra vindo do outro lado do mar, o inverno rigoroso chega ao fim. Segundo a lenda, o amor deste Pokémon dá origem ao surgimento de uma nova vida em Hisui.'),
(906, 'Sprigatito', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/906.png', 'Seu pelo fofo tem composição semelhante à das plantas. Este Pokémon lava frequentemente o rosto para evitar que resseque.'),
(907, 'Floragato', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/907.png', 'Floragato maneja habilmente a videira escondida sob seu longo pelo, batendo o duro botão de flor contra seus oponentes.'),
(908, 'Meowscarada', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/908.png', 'Este Pokémon usa o pelo reflexivo que reveste sua capa para camuflar o caule de sua flor, criando a ilusão de que a flor está flutuando.'),
(909, 'Fuecoco', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/909.png', 'Encontra-se sobre rochas quentes e utiliza o calor absorvido pelas suas escamas quadradas para criar energia de fogo.'),
(910, 'Crocalor', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/910.png', 'A combinação da energia do fogo de Crocalor e da vitalidade transbordante fez com que uma bola de fogo em forma de ovo aparecesse na cabeça do Pokémon.'),
(911, 'Skeledirge', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/911.png', 'O pássaro de fogo muda de forma quando Skeledirge canta. Há rumores de que o pássaro nasceu quando a bola de fogo na cabeça de Skeledirge ganhou alma.'),
(912, 'Quaxly', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/912.png', 'Este Pokémon migrou de terras distantes para Paldea há muito tempo. O gel secretado pelas penas repele a água e a sujeira.'),
(913, 'Quaxwell', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/913.png', 'Esses Pokémon correm constantemente em águas rasas para treinar as pernas e depois competem entre si para ver qual deles chuta com mais graça.'),
(914, 'Quaquaval', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/914.png', 'Um único chute de um Quaquaval pode fazer um caminhão rolar. Este Pokémon usa suas pernas poderosas para realizar danças impressionantes em terras distantes.'),
(915, 'Lechonk', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/915.png', 'Ele procura comida o dia todo. Possui um olfato apurado, mas não o utiliza para outra coisa senão forragear.'),
(916, 'Oinkologne-male', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/916.png', 'Oinkologne orgulha-se da sua pele fina e brilhante. Ele emite um perfume concentrado pela ponta da cauda.'),
(917, 'Tarountula', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/917.png', 'O novelo de fios enrolado em seu corpo é elástico o suficiente para desviar as foices de Scyther, o inimigo natural deste Pokémon.'),
(918, 'Spidops', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/918.png', 'Ele se agarra a galhos e tetos com seus fios e se move sem fazer barulho. Ele tira sua presa antes mesmo que ela perceba.'),
(919, 'Nymble', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/919.png', 'Tem o terceiro conjunto de pernas dobrado. Quando está em uma situação difícil, este Pokémon salta mais de 9 metros usando a força de suas pernas.'),
(920, 'Lokix', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/920.png', 'Quando decide lutar com tudo, ele fica de pé sobre as pernas anteriormente dobradas para entrar no modo Showdown. Ele neutraliza seus inimigos em pouco tempo.'),
(921, 'Pawmi', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/921.png', 'Possui bolsas elétricas subdesenvolvidas nas bochechas. Esses sacos só podem produzir eletricidade se Pawmi os esfregar furiosamente com as almofadas das patas dianteiras.'),
(922, 'Pawmo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/922.png', 'Quando seu grupo é atacado, Pawmo é o primeiro a entrar na batalha, derrotando os inimigos com uma técnica de luta que utiliza choques elétricos.'),
(923, 'Pawmot', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/923.png', 'Este Pokémon normalmente reage lentamente, mas assim que entra na batalha, ele derrubará seus inimigos com movimentos extremamente rápidos.'),
(924, 'Tandemaus', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/924.png', 'Exibindo grande trabalho em equipe, eles usam seus incisivos para cortar pedaços de qualquer material que possa ser útil para um ninho e depois fogem com eles.'),
(925, 'Maushold-family-of-four', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/925.png', 'Eles constroem ninhos enormes com muitos cômodos que são utilizados para diversos fins, como comer e dormir.'),
(926, 'Fidough', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/926.png', 'Este Pokémon é macio e úmido ao toque. O fermento no hálito de Fidough induz fermentação nas proximidades do Pokémon.'),
(927, 'Dachsbun', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/927.png', 'O aroma agradável que emana do corpo deste Pokémon ajuda o trigo a crescer, por isso Dachsbun é apreciado pelas aldeias agrícolas.'),
(928, 'Smoliv', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/928.png', 'Ele se protege dos inimigos emitindo óleo da fruta em sua cabeça. Este óleo é amargo e adstringente o suficiente para fazer alguém estremecer.'),
(929, 'Dolliv', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/929.png', 'Dolliv compartilha seu óleo saboroso e com aroma fresco com outras pessoas. Esta espécie coexiste com os humanos desde tempos idos.'),
(930, 'Arboliva', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/930.png', 'Este Pokémon calmo é muito compassivo. Ele compartilhará seu óleo delicioso e rico em nutrientes com Pokémon enfraquecidos.'),
(931, 'Squawkabilly-green-plumage', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/931.png', 'Esses Pokémon preferem viver em cidades. Eles formam bandos com base na cor de suas penas e lutam por território.'),
(932, 'Nacli', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/932.png', 'Nasceu em uma camada de sal-gema nas profundezas da terra. Esta espécie era particularmente apreciada antigamente, pois compartilhavam o precioso sal.'),
(933, 'Naclstack', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/933.png', 'Este Pokémon cura suas presas a seco borrifando sal sobre elas. O processo de cura rouba a água do corpo da presa.'),
(934, 'Garganacl', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/934.png', 'Garganacl esfregará as pontas dos dedos e salpicará sal nos Pokémon feridos. Mesmo feridas graves cicatrizarão rapidamente depois.'),
(935, 'Charcadet', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/935.png', 'O carvão queimado ganhou vida e se tornou um Pokémon. Possuindo um espírito de luta ardente, Charcadet enfrentará até adversários difíceis.'),
(936, 'Armarouge', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/936.png', 'Armarouge evoluiu através do uso de um conjunto de armadura que pertencia a um distinto guerreiro. Este Pokémon é incrivelmente leal.'),
(937, 'Ceruledge', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/937.png', 'As lâminas de fogo em seus braços queimam ferozmente com o ressentimento persistente de um portador de espada que caiu antes de atingir seu objetivo.'),
(938, 'Tadbulb', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/938.png', 'Tadbulb balança o rabo para gerar eletricidade. Se sentir perigo, fará sua cabeça piscar para alertar seus aliados.'),
(939, 'Bellibolt', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/939.png', 'Quando este Pokémon expande e contrai o seu corpo instável, o dínamo do umbigo no seu estômago produz uma enorme quantidade de eletricidade.'),
(940, 'Wattrel', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/940.png', 'Quando suas asas são atingidas pelo vento, seus ossos produzem eletricidade. Este Pokémon mergulha no oceano, capturando suas presas eletrocutando-as.'),
(941, 'Kilowattrel', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/941.png', 'Kilowattrel infla sua bolsa na garganta para amplificar sua eletricidade. Ao navegar no vento, este Pokémon pode voar mais de 430 milhas por dia.'),
(942, 'Maschiff', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/942.png', 'Ele sempre faz cara feia na tentativa de fazer com que os oponentes levem isso a sério, mas até mesmo crianças chorando cairão na gargalhada ao verem o rosto de Maschiff.'),
(943, 'Mabosstiff', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/943.png', 'Este Pokémon pode armazenar energia em sua grande barbela. Mabosstiff libera essa energia de uma só vez para afastar os inimigos.'),
(944, 'Shroodle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/944.png', 'Embora geralmente seja um Pokémon suave, ele afundará seus dentes frontais afiados e encharcados de veneno em qualquer um que o irrite, causando paralisia no objeto de sua ira.'),
(945, 'Grafaiai', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/945.png', 'A cor da saliva venenosa depende do que o Pokémon come. Grafaiai cobre os dedos com saliva e desenha padrões nas árvores das florestas.'),
(946, 'Bramblin', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/946.png', 'Uma alma incapaz de seguir para a vida após a morte foi levada pelo vento até se enroscar na grama seca e se tornar um Pokémon.'),
(947, 'Brambleghast', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/947.png', 'Ele abrirá os galhos de sua cabeça para envolver sua presa. Depois de absorver toda a energia vital de que necessita, ele expele a presa e a descarta.'),
(948, 'Toedscool', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/948.png', 'Toedscool vive em florestas abafadas. As abas que caem de seu corpo são mastigáveis ​​e muito deliciosas.'),
(949, 'Toedscruel', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/949.png', 'Esses Pokémon se reúnem em grupos e formam colônias nas profundezas das florestas. Eles absolutamente odeiam quando estranhos se aproximam.'),
(950, 'Klawf', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/950.png', 'Klawf está pendurado de cabeça para baixo em penhascos, esperando por uma presa. Mas Klawf não consegue permanecer nesta posição por muito tempo porque seu sangue sobe à cabeça.'),
(951, 'Capsakid', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/951.png', 'Quanto mais luz solar este Pokémon toma banho, mais substâncias químicas picantes são produzidas pelo seu corpo e, portanto, mais picantes se tornam os seus movimentos.'),
(952, 'Scovillain', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/952.png', 'A ruiva converte produtos químicos picantes em energia de fogo e atinge a área ao redor com um fluxo de chamas super picante.'),
(953, 'Rellor', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/953.png', 'Este Pokémon cria uma bola de lama misturando areia e terra com energia psíquica. Ele valoriza mais sua bola de lama do que sua própria vida.'),
(954, 'Rabsca', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/954.png', 'O corpo que sustenta a bola mal se move. Portanto, pensa-se que o verdadeiro corpo deste Pokémon está, na verdade, dentro da bola.'),
(955, 'Flittle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/955.png', 'Os dedos dos pés de Flittle levitam cerca de meia polegada acima do solo por causa do poder psíquico emitido pelos babados na barriga do Pokémon.'),
(956, 'Espathra', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/956.png', 'Ele imobiliza os oponentes banhando-os com o poder psíquico de seus grandes olhos. Apesar da aparência, possui um temperamento cruel.'),
(957, 'Tinkatink', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/957.png', 'Ele balança seu martelo artesanal para se proteger, mas o martelo é frequentemente roubado por Pokémon que comem metal.'),
(958, 'Tinkatuff', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/958.png', 'Este Pokémon atacará grupos de Pawniard e Bisharp, coletando metal deles para criar um martelo grande e resistente.'),
(959, 'Tinkaton', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/959.png', 'Este Pokémon inteligente tem uma disposição muito ousada. Ele joga pedras no céu com seu martelo, visando voar Corviknight.'),
(960, 'Wiglett', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/960.png', 'Este Pokémon pode sentir o cheiro de uma Veluza a pouco mais de 20 metros de distância e se esconder na areia.'),
(961, 'Wugtrio', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/961.png', 'Possui temperamento cruel, ao contrário do que sua aparência pode sugerir. Ele envolve a presa com seus longos corpos e depois a arrasta para sua toca.'),
(962, 'Bombirdier', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/962.png', 'Ele reúne as coisas em um avental feito de penas adicionadas às penas do peito do Pokémon e, em seguida, deixa essas coisas cair de lugares altos para se divertir.'),
(963, 'Finizen', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/963.png', 'Gosta de brincar com outros da sua espécie usando o anel de água na cauda. Ele usa ondas ultrassônicas para sentir as emoções de outras criaturas vivas.'),
(964, 'Palafin-zero', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/964.png', 'Este Pokémon muda de aparência se ouvir seus aliados pedindo ajuda. Palafin nunca mostrará a ninguém o seu momento de transformação.'),
(965, 'Varoom', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/965.png', 'Diz-se que este Pokémon nasceu quando um Pokémon venenoso desconhecido entrou e inspirou um motor deixado em uma fábrica de processamento de sucata.'),
(966, 'Revavroom', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/966.png', 'Ele cria um gás a partir de veneno e minerais das rochas. Em seguida, detona o gás em seus cilindros – agora em número de oito – para gerar energia.'),
(967, 'Cyclizar', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/967.png', 'Aparentemente, o Cyclizar permite que as pessoas andem de costas desde os tempos antigos. Representações disso foram encontradas em murais de 10.000 anos.'),
(968, 'Orthworm', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/968.png', 'Quando atacado, este Pokémon empunhará os tentáculos de seu corpo como se fossem punhos e atacará o oponente com uma tempestade de socos.'),
(969, 'Glimmet', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/969.png', 'Absorve nutrientes das paredes das cavernas. As pétalas que usa são feitas de veneno cristalizado.'),
(970, 'Glimmora', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/970.png', 'Quando este Pokémon detecta perigo, ele abrirá suas pétalas cristalinas e raios de fogo de seu corpo cônico.'),
(971, 'Greavard', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/971.png', 'Diz-se que um Pokémon cão que morreu na natureza sem nunca ter interagido com um humano renasceu como este Pokémon.'),
(972, 'Houndstone', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/972.png', 'Houndstone passa a maior parte do tempo dormindo em cemitérios. Entre todos os Pokémon caninos, este é o mais leal ao seu dono.'),
(973, 'Flamigo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/973.png', 'Este Pokémon aparentemente amarra a base do pescoço com um nó para que a energia armazenada em sua barriga não escape de seu bico.'),
(974, 'Cetoddle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/974.png', 'Esta espécie deixou o oceano e começou a viver na terra há muito tempo. Parece estar intimamente relacionado com Wailmer.'),
(975, 'Cetitan', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/975.png', 'Este Pokémon vagueia por áreas nevadas e geladas. Ele protege seu corpo com músculos poderosos e uma espessa camada de gordura sob a pele.'),
(976, 'Veluza', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/976.png', 'Quando Veluza descarta carne desnecessária, sua mente fica afiada e seu poder psíquico aumenta. A polpa restante tem um sabor suave, mas delicioso.'),
(977, 'Dondozo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/977.png', 'Este Pokémon é um glutão, mas é ruim para conseguir comida. Ele se junta a um Tatsugiri para capturar a presa.'),
(978, 'Tatsugiri-curly', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/978.png', 'Este é um pequeno Pokémon dragão. Vive dentro da foz do Dondozo para se proteger dos inimigos externos.'),
(979, 'Annihilape', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/979.png', 'Quando a sua raiva ultrapassou um ponto crítico, este Pokémon ganhou um poder que não está limitado aos limites do seu corpo físico.'),
(980, 'Clodsire', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/980.png', 'Quando atacado, este Pokémon retaliará espetando espinhos grossos em seu corpo. É uma jogada arriscada que coloca tudo em risco.'),
(981, 'Farigiraf', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/981.png', 'Agora que as ondas cerebrais da cabeça e da cauda estão sincronizadas, o poder psíquico deste Pokémon é 10 vezes mais forte que o de Girafarig.'),
(982, 'Dudunsparce-two-segment', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/982.png', 'Este Pokémon usa sua cauda dura para fazer seu ninho, abrindo buracos na rocha subterrânea. O ninho pode atingir comprimentos de mais de seis milhas.'),
(983, 'Kingambit', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/983.png', 'Somente um Bisharp que esteja acima de todos os outros em seu vasto exército pode evoluir para Kingambit.'),
(984, 'Great-tusk', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/984.png', 'Avistamentos deste Pokémon ocorreram nos últimos anos. O nome Great Tusk foi tirado de uma criatura listada em um determinado livro.'),
(985, 'Scream-tail', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/985.png', 'Houve apenas um relato de avistamento deste Pokémon. Assemelha-se a uma criatura misteriosa retratada em um antigo diário de expedição.'),
(986, 'Brute-bonnet', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/986.png', 'É possível que a criatura listada como Brute Bonnet em um determinado livro possa realmente ser este Pokémon.'),
(987, 'Flutter-mane', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/987.png', 'Este Pokémon possui características semelhantes às de Flutter Mane, criatura mencionada em determinado livro.'),
(988, 'Slither-wing', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/988.png', 'Este misterioso Pokémon tem algumas semelhanças com uma criatura que um livro antigo apresentou como Slither Wing.'),
(989, 'Sandy-shocks', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/989.png', 'Não existem registros deste Pokémon sendo capturado. Faltam dados, mas as características do Pokémon correspondem às de uma criatura mostrada em um diário de expedição.'),
(990, 'Iron-treads', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/990.png', 'Este Pokémon se assemelha muito a uma arma científica que uma revista paranormal afirmou ter sido enviada a este planeta por alienígenas.'),
(991, 'Iron-bundle', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/991.png', 'Seu formato é semelhante ao de um robô apresentado em um artigo de revista paranormal. Diz-se que o robô foi criado por uma civilização antiga.'),
(992, 'Iron-hands', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/992.png', 'É muito parecido com um ciborgue coberto exclusivamente por uma revista paranormal. Dizia-se que o ciborgue era a forma modificada de um determinado atleta.'),
(993, 'Iron-jugulis', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/993.png', 'Assemelha-se a um certo Pokémon apresentado em uma revista paranormal, descrito como filho de um Hydreigon que se apaixonou por um robô.'),
(994, 'Iron-moth', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/994.png', 'Este Pokémon se assemelha a um objeto desconhecido descrito em uma revista paranormal como um OVNI enviado para observar a humanidade.'),
(995, 'Iron-thorns', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/995.png', 'Tem algumas semelhanças com um Pokémon apresentado em uma revista duvidosa como um Tyranitar de um bilhão de anos no futuro.'),
(996, 'Frigibax', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/996.png', 'Frigibax absorve calor através de sua barbatana dorsal e converte o calor em energia gelada. Quanto mais alta a temperatura, mais energia o Frigibax armazena.'),
(997, 'Arctibax', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/997.png', 'Arctibax congela o ar ao seu redor, protegendo seu rosto com uma máscara de gelo e transformando sua barbatana dorsal em uma lâmina de gelo.'),
(998, 'Baxcalibur', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/998.png', 'Este Pokémon libera ar criogênico de sua boca. Este ar pode congelar instantaneamente até lava líquida quente.'),
(999, 'Gimmighoul', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/999.png', 'Este Pokémon nasceu dentro de um baú de tesouro há cerca de 1.500 anos. Suga a força vital dos canalhas que tentam roubar o tesouro.'),
(1000, 'Gholdengo', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1000.png', 'Seu corpo parece ser composto por 1.000 moedas. Este Pokémon se dá bem com outras pessoas e é rápido em fazer amizade com qualquer pessoa.'),
(1001, 'Wo-chien', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1001.png', 'O rancor de uma pessoa punida por escrever as más ações do rei em tábuas de madeira se revestiu de folhas mortas para se tornar um Pokémon.'),
(1002, 'Chien-pao', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1002.png', 'Este Pokémon pode controlar 100 toneladas de neve caída. Ele brinca inocentemente, entrando e saindo das avalanches que causou.'),
(1003, 'Ting-lu', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1003.png', 'O medo derramado em um antigo recipiente ritual se revestiu de pedras e sujeira para se tornar um Pokémon.'),
(1004, 'Chi-yu', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1004.png', 'Ele controla chamas que queimam a mais de 5.400 graus Fahrenheit. Ele nada casualmente no mar de lava que cria ao derreter rocha e areia.'),
(1005, 'Roaring-moon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1005.png', 'É possível que esta seja a criatura listada como Roaring Moon em um diário de expedição que ainda guarda muitos mistérios.'),
(1006, 'Iron-valiant', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1006.png', 'Tem algumas semelhanças com a invenção de um cientista maluco publicada em uma revista paranormal.'),
(1007, 'Koraidon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1007.png', 'Este parece ser o Rei Alado mencionado em um antigo diário de expedição. Diz-se que dividiu a terra com os punhos nus.'),
(1008, 'Miraidon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1008.png', 'Muito permanece desconhecido sobre esta criatura. Assemelha-se ao Cyclizar, mas é muito mais implacável e poderoso.'),
(1009, 'Walking-wake', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1009.png', 'Esta criatura feroz está envolta em mistério. Tem o nome de um monstro aquático mencionado em um antigo diário de expedição.'),
(1010, 'Iron-leaves', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1010.png', 'Muitas de suas características físicas correspondem às de um Virizion do futuro que foi abordado em uma revista paranormal.'),
(1011, 'Dipplin', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1011.png', 'Dipplin são duas criaturas em um Pokémon. Sua evolução foi desencadeada por uma maçã especial cultivada em apenas um lugar.'),
(1012, 'Poltchageist', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1012.png', 'Supostamente, o arrependimento de um mestre da cerimônia do chá que morreu antes de aperfeiçoar seu ofício permaneceu em algum matcha e se tornou um Pokémon.'),
(1013, 'Sinistcha', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1013.png', 'Ele finge ser chá, tentando enganar as pessoas para que o bebam, para que possa drenar sua força vital. Seu estratagema geralmente não tem sucesso.'),
(1014, 'Okidogi', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1014.png', 'Depois que todos os seus músculos foram estimulados pela corrente tóxica em volta do pescoço, Okidogi se transformou e ganhou um físico poderoso.'),
(1015, 'Munkidori', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1015.png', 'A cadeia é feita de toxinas que melhoram as capacidades. Estimulou o cérebro de Munkidori e fez com que os poderes psíquicos do Pokémon florescessem.'),
(1016, 'Fezandipiti', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1016.png', 'Fezandipiti deve sua bela aparência e voz adorável aos estimulantes tóxicos que emanam da corrente enrolada em seu corpo.'),
(1017, 'Ogerpon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1017.png', 'O tipo deste Pokémon muda com base na máscara que ele usa. Ele confunde seus inimigos com movimentos e chutes ágeis.'),
(1018, 'Archaludon', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1018.png', 'Ele coleta eletricidade estática do ambiente. Os raios que ele lança quando está de quatro são tremendamente poderosos.'),
(1019, 'Hydrapple', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1019.png', 'Sete sirpentes vivem dentro de uma maçã feita de calda. O Syrpent no centro é o comandante.'),
(1020, 'Gouging-fire', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1020.png', 'Existem poucos relatos de que esta criatura foi avistada. Um pequeno vídeo mostra-o furioso e jorrando pilares de chamas.'),
(1021, 'Raging-bolt', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1021.png', 'Diz-se que incinera tudo ao seu redor com raios lançados de seu pelo. Muito pouco se sabe sobre esta criatura.'),
(1022, 'Iron-boulder', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1022.png', 'Assemelha-se a um Pokémon descrito em uma revista duvidosa como um Terrakion que foi modificado por uma organização maligna.'),
(1023, 'Iron-crown', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1023.png', 'Assemelha-se a um objeto misterioso apresentado em uma revista paranormal como uma arma de ponta em forma de Cobalion.'),
(1024, 'Terapagos', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1024.png', 'Terápagos se protege usando seu poder de transformar energia em cristais duros. Este Pokémon é a fonte do fenômeno Terastal.'),
(1025, 'Pecharunt', false, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1025.png', 'Ele alimenta outros mochi tóxicos que despertam desejos e capacidades. Aqueles que comem o mochi ficam sob o controle de Pecharunt, acorrentados à sua vontade.'),
